function render(){settle();syncCats();
  const d=new Date();
  $('#root').innerHTML=`<header><h1 style="display:flex;align-items:center;gap:8px">${S.settings.logo?`<img src="${S.settings.logo}" alt="" style="width:42px;height:42px;border-radius:50%;object-fit:cover;background:#fff">`:'🍊'} ${esc(S.settings.shop)}<button data-a="refresh" title="تحديث" style="margin-inline-start:auto;background:rgba(255,255,255,.18);color:#fff;border:0;border-radius:10px;padding:7px 12px;font:inherit;font-size:15px;cursor:pointer">🔄 تحديث</button></h1><div class="sub"><span>${d.getDate()} ${MONTHS[d.getMonth()]} ${d.getFullYear()}</span><span id="cloudst">${window.CLOUD?CLOUD.status:''}</span></div></header>
  <nav>${TABS.filter(t=>showAll||S.settings.simple===false||['home','sell','needs'].includes(t[0])||t[0]===tab).map(t=>`<button data-go="${t[0]}" class="${t[0]===tab?'on':''}">${t[1]}</button>`).join('')}${S.settings.simple===false?'':`<button data-a="more" style="color:var(--pri)">${showAll?'▴ أقل':'المزيد ▾'}</button>`}</nav><main>${V[tab]()}${tab==='home'||tab==='needs'?'':notesCard(tab)}</main><div id="modal"><div class="box"></div></div>`;
  const on=document.querySelector('nav .on');if(on)on.scrollIntoView({inline:'center',block:'nearest'});
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-go],[data-a]');if(!b)return;if(b.dataset.go)return go(b.dataset.go);if(ISSTAFF&&blocked(b.dataset.a,b.dataset.id)){e.preventDefault();return toast('🔒 هذي للمالك بس')}const fn=A[b.dataset.a];if(fn)fn(b.dataset.id,b,e)});
document.addEventListener('click',e=>{if(e.target.id==='modal')closeM()});

const V={};
V.home=()=>{const t=salesSum(inRange(S.sales,sod(Date.now())));const y=salesSum(inRange(S.sales,sod(Date.now())-DAY,sod(Date.now())));const m=month();const be=breakEven();const n=needs();
  const urgent=n.filter(x=>x.st==='b'),soon=n.filter(x=>x.st==='w');const low=lowProds();const norec=S.prods.filter(p=>!hasRec(p)).length;
  const budLeft=S.settings.budget-m.pur;
  const pct=be.cups?Math.min(100,t.cups/be.cups*100):0;
  let al='';
  if(S.demo)al+=`<div class="alert a-w">👋 هذه بيانات تجريبية لتوضيح طريقة العمل. عدّل المواد والأصناف حسب محلك، ثم امسح التجريبي من <a href="#prefs" data-go="prefs">الإعدادات</a>.</div>`;
  if(urgent.length)al+=`<div class="alert a-b">🔴 مواد تحت الحد الأدنى: <b>${urgent.map(x=>esc(x.i.name)).join('، ')}</b> — <a href="#needs" data-go="needs">قائمة الشراء</a></div>`;
  if(soon.length)al+=`<div class="alert a-w">🟠 تخلص خلال ${S.settings.cover} أيام: ${soon.map(x=>esc(x.i.name)).join('، ')}</div>`;
  if(low.length)al+=`<div class="alert a-w">💸 أصناف ربحها ضعيف (التكلفة فوق ${S.settings.target+8}% من السعر): <b>${low.map(p=>esc(p.name)).join('، ')}</b> — <a href="#items" data-go="items">راجع التسعير</a></div>`;
  const nest=S.prods.filter(p=>p.est).length;if(nest)al+=`<div class="alert a-w">🧪 ${nest} وصفة تقديرية (العصيرات) — راجع كم مل فاكهة في الكوب الوسط عندك وصحّحها من <a href="#items" data-go="items">الأصناف</a>، وبعدها يطلع ربحك الحقيقي</div>`;
  if(norec)al+=`<div class="alert a-w">📝 ${norec} صنف بدون وصفة، ما نقدر نحسب ربحه — <a href="#items" data-go="items">أضف المكونات</a></div>`;
  if(budLeft<0)al+=`<div class="alert a-b">⚠️ تجاوزت ميزانية المقاضي لهذا الشهر بـ ${C(-budLeft)}</div>`;
  if(!al)al='<div class="alert a-ok">✅ كل شيء تمام اليوم</div>';
  return `${homePeriod()}
  `};

function tips(){const out=[];const from=sod(Date.now())-13*DAY;const by={};inRange(S.sales,from).forEach(s=>s.items.forEach(i=>{const o=by[i.p]=by[i.p]||{q:0,pr:0,n:i.n};o.q+=i.q;o.pr+=(i.price-i.cost)*i.q}));
  const arr=Object.entries(by).map(([id,o])=>({id,...o})).sort((a,b)=>b.q-a.q);const be=breakEven();
  if(arr.length){const top=arr[0];out.push(`<b>${esc(top.n)}</b> الأكثر طلباً (${top.q} كوب في أسبوعين). رفع سعره ريال واحد يزيد دخلك تقريباً <b>${C(top.q/14*30)}</b> شهرياً.`)}
  lowProds().slice(0,4).forEach(p=>{const sz=sizesOf(p);const s=sz.find(s=>s.id==='M')||sz[0];const c=cost(p,s.id),pr=+p.prices[s.id];out.push(`<b>${esc(vname(p,s.id))}</b>: تكلفته ${C(c)} وتبيعه ${C(pr)} (${Math.round(c/pr*100)}%). اقتراح: ${C(sugPrice(c))}، أو قلّل كمية الفاكهة وزِد الثلج.`)});
  const wst=inRange(S.waste,mStart()).reduce((a,b)=>a+b.cost,0);if(wst>0)out.push(`التالف هذا الشهر ${C(wst)}. اشترِ الفواكه سريعة التلف (فراولة، موز) بكميات يومية أصغر حسب صفحة الاحتياج.`);
  if(be.m.cupsDay&&be.m.cupsDay<be.cups)out.push(`متوسط بيعك ${Math.round(be.m.cupsDay)} كوب/يوم وأنت تحتاج ${be.cups}. جرّب عرض "الكوب الثاني بنص السعر" في أوقات الركود أو كومبو مع وجبة خفيفة لرفع متوسط الطلب.`);
  const hrs={};inRange(S.sales,from).forEach(s=>{const h=new Date(s.t).getHours();hrs[h]=(hrs[h]||0)+1});const hs=Object.entries(hrs).sort((a,b)=>b[1]-a[1]);if(hs.length>2)out.push(`ذروة الطلب الساعة ${hl(+hs[0][0])}. جهّز العصيرات والثلج قبلها، وخلّ أقل عمالة في الساعات الهادئة.`);
  return out.length?out.map(t=>`<div class="tip">${t}</div>`).join(''):'<div class="empty">سجّل مبيعات أكثر عشان تظهر لك اقتراحات.</div>'}
const hl=h=>(h%12||12)+(h<12?' ص':' م');
const sugPrice=c=>Math.ceil(c/(S.settings.target/100)*2)/2;

let scat=null,sedit=false,pcat='الكل';
const allCats=()=>{const c=(S.cats||[]).filter(c=>S.prods.some(p=>p.cat===c));S.prods.forEach(p=>{if(!c.includes(p.cat))c.push(p.cat)});return c};
V.sell=()=>{const items=Object.entries(cart).filter(([,q])=>q>0);const kp=k=>{const [pid,sid]=k.split('|');return{p:PROD(pid),sid}};const tot=items.reduce((s,[k,q])=>{const {p,sid}=kp(k);return s+(p?+p.prices[sid]:0)*q},0);const today=inRange(S.sales,sod(Date.now())).slice().reverse();
  const cats=allCats();if(!scat||!cats.includes(scat))scat=cats[0];
  const imps=(S.imports||[]).slice().reverse().slice(0,5);
  const pcats=allCats().filter(c=>S.prods.some(p=>p.cat===c&&sizesOf(p).length));if(pcat!=='الكل'&&!pcats.includes(pcat))pcat='الكل';
  const pshow=S.prods.filter(p=>sizesOf(p).length&&(pcat==='الكل'||p.cat===pcat));
  const prodsCard=`<div class="card"><h3>المنتجات <span><span class="mut">${pshow.length} صنف</span> <button class="btn ghost sm" style="padding:3px 10px" data-a="prod" title="إضافة صنف">＋</button></span></h3><div class="row" style="overflow-x:auto;flex-wrap:nowrap;margin-bottom:10px;padding-bottom:4px">${['الكل',...pcats].map(c=>{const n=S.prods.filter(p=>sizesOf(p).length&&(c==='الكل'||p.cat===c)).length;return `<button class="btn sm ${c===pcat?'':'ghost'}" style="flex:0 0 auto" data-a="pcat" data-id="${esc(c)}">${esc(c)} <span style="font-size:11px;font-weight:500;opacity:.75">${n}</span></button>`}).join('')}</div><div class="grid">${pshow.map(p=>`<button class="pbtn" data-a="pinfo" data-id="${p.id}"><b>${esc(p.name)}</b></button>`).join('')}</div></div>`;
  return `${prodsCard}<div class="card"><h3>مبيعات اليوم <span><span class="mut">${today.length} طلب · ${C(today.reduce((a,x)=>a+x.total,0))}</span> <button class="btn sm" data-a="salesin">📥 إضافة</button></span></h3>${today.length?`<table><tr><th>الوقت</th><th>الأصناف</th><th>الدفع</th><th>المبلغ</th><th></th></tr>${today.slice(0,40).map(s=>`<tr><td class="mut">${new Date(s.t).toLocaleTimeString('en',{hour:'numeric',minute:'2-digit'})}</td><td>${s.items.map(i=>esc(i.n)+(i.q>1?' ×'+i.q:'')).join('، ')}</td><td class="mut">${s.pay}</td><td>${f2(s.total)}</td><td><button class="btn ghost sm" data-a="delsale" data-id="${s.id}">✕</button></td></tr>`).join('')}</table>`:'<div class="empty">ما فيه مبيعات اليوم</div>'}</div>`};

const inPack=i=>i&&i.buyIn==='pack'&&+i.packSize>0;
const qtyTxt=(i,q)=>inPack(i)?f2(Math.ceil(q/i.packSize))+' '+esc(i.pack||'كرتون'):f2(q)+' '+esc(i.unit);
const estOf=x=>x.manual&&(S.extraList||[]).some(e=>e.i===x.i.id&&e.price>0)?x.est:inPack(x.i)?Math.ceil(x.buy/x.i.packSize)*x.i.packSize*x.i.cost:x.est;
document.addEventListener('change',e=>{if(e.target.classList.contains('nd_cv')){const i=ING(e.target.dataset.id);if(i){i.cv=pF(e.target.value)||0;save('✓ '+i.name+': يكفي '+(i.cv||S.settings.cover)+' يوم');render()}}
  if(e.target.classList.contains('nd_g')){const v=pF(e.target.value);if(v>0){S.settings.cover=v;save('✓ المقاضي تكفي '+v+' أيام');render()}}});
function needList(){const n=needs();const m={};const U=usage();n.forEach(x=>{const lv=stLevel(x.i,U);if(lv==='t-ok')return;x.st=lv==='t-b'?'b':'w';if(!(x.buy>0)){const lp=S.purchases.filter(p=>p.ing===x.i.id).sort((a,c)=>c.t-a.t)[0];x.buy=(lp&&lp.q)||(+x.i.cvQ>0?+x.i.cvQ:0)||(+x.i.packSize>0?+x.i.packSize:1);x.est=x.buy*(+x.i.cost||0)}m[x.i.id]=x});(S.extraList||[]).forEach(e=>{const i=ING(e.i);if(!i)return;const x=m[e.i];if(x){x.buy=Math.max(x.buy,e.q);x.est=e.price>0?e.price:x.buy*i.cost;x.manual=true}else{const b=n.find(y=>y.i.id===e.i)||{cv:+i.cv||S.settings.cover};m[e.i]={i,d:0,cv:b.cv,left:Infinity,buy:e.q,est:e.price>0?e.price:e.q*i.cost,st:'ok',manual:true}}});return{n,list:Object.values(m)}}
V.needs=()=>{const {n,list}=needList();const tot=list.reduce((s,x)=>s+estOf(x),0);const m=month();const left=S.settings.budget-m.pur;const ord={b:0,w:1,ok:2};
  const unk=n.filter(x=>!x.d&&!x.i.min&&!x.i.trk&&!(+x.i.every>0)&&['منظفات','بلاستيك وتغليف','ثلج','أغراض الحلا','مجمدات'].includes(x.i.cat)&&!S.prods.some(p=>p.recipe.some(r=>r.i===x.i.id))&&!S.sizes.some(z=>(z.pk||[]).includes(x.i.id)));
  const ctl=x=>!x.i.packSize?'':`<div class="row" style="gap:4px;margin-top:5px;flex-wrap:nowrap">${x.i.packSize?`<span style="display:inline-flex;border:1px solid var(--line);border-radius:8px;overflow:hidden">${[['unit',x.i.unit],['pack',x.i.pack||'كرتون']].map(([k,l])=>`<button class="btn sm" style="border-radius:0;${(k==='pack')===inPack(x.i)?'':'background:transparent;color:var(--mut)'}" data-a="ndunit" data-id="${x.i.id}|${k}">${esc(l)}</button>`).join('')}</span>`:''}</div>`;
  const row=x=>`<tr><td>${esc(x.i.name)}${x.manual?` <button class="btn ghost sm" style="padding:1px 7px" data-a="needdel" data-id="${x.i.id}">✕</button>`:''}</td><td>${x.st==='b'?'<span class="tag t-b">عاجل</span>':x.st==='w'?'<span class="tag t-w">يخلص اليوم</span>':'<span class="tag t-ok">مضاف</span>'}</td><td><button class="btn sec sm" data-a="qbuy" data-id="${x.i.id}">اشتريت</button></td></tr>`;
  return `<div class="card"><h3>قائمة المقاضي <button class="btn sm" data-a="needadd">+ إضافة</button></h3>
  ${list.length?ICATS.map(c=>{const g=list.filter(x=>(x.i.cat||'أخرى')===c).sort((a,b)=>ord[a.st]-ord[b.st]||b.est-a.est);if(!g.length)return'';const st=g.reduce((a,x)=>a+estOf(x),0);
    return `<div class="row" style="margin-top:14px"><b style="font-size:15px">${c}</b></div><table>${g.map(row).join('')}</table>`}).join('')+`
  <button class="btn full sec" style="margin-top:12px" data-a="copylist">📋 نسخ القائمة كاملة (للواتساب)</button>`:'<div class="empty">✅ المخزون يكفي — ما تحتاج تشتري شي الحين</div>'}
  </div>`};

let stcat='الكل';
V.stock=()=>{const pur=S.purchases.slice().sort((a,b)=>b.t-a.t).slice(0,25);const ws=S.waste.slice().sort((a,b)=>b.t-a.t).slice(0,10);
  return `<div class="row" style="margin-bottom:12px"><button class="btn sp" data-a="buy">🛒 تسجيل مشتريات</button><button class="btn sec sp" data-a="waste">🗑️ تسجيل تالف</button></div>
  <div class="card"><h3>المواد والاحتياجات <button class="btn sec sm" data-a="ing">+ مادة</button></h3>
  <div class="row" style="overflow-x:auto;flex-wrap:nowrap;margin-bottom:8px;padding-bottom:4px">${['الكل',...ICATS.filter(c=>S.ings.some(i=>(i.cat||'أخرى')===c))].map(c=>`<button class="btn sm ${c===stcat?'':'ghost'}" style="flex:0 0 auto" data-a="stcat" data-id="${c}">${c}</button>`).join('')}</div>
  ${(()=>{const U=usage();return `<table><tr><th>المادة</th><th>المخزون الحالي</th><th></th></tr>${S.ings.filter(i=>stcat==='الكل'||(i.cat||'أخرى')===stcat).map(i=>{const lv=stLevel(i,U);return `<tr><td>${esc(i.name)}</td><td><span class="tag ${lv}" style="font-size:15px;min-width:44px;text-align:center">${f2(inPack(i)?r2(i.stock/i.packSize):r2(i.stock))}</span></td><td style="white-space:nowrap"><button class="btn sec sm" data-a="qbuy" data-id="${i.id}">اشتريت</button> <button class="btn ghost sm" data-a="ing" data-id="${i.id}">✏️</button></td></tr>`}).join('')}</table>
  <p class="mut" style="margin-top:8px"><span class="tag t-b">أحمر</span> خلص · <span class="tag t-w">برتقالي</span> باقي يوم أو أقل</p>`})()}
  </div>
  <div class="card"><h3>آخر المشتريات</h3>${pur.length?`<table><tr><th>التاريخ</th><th>المادة</th><th>الكمية</th><th>المبلغ</th><th>المورد</th><th></th></tr>${pur.map(p=>{const i=ING(p.ing);return `<tr><td class="mut">${dk(p.t).slice(5)}</td><td>${esc(i?i.name:'—')}</td><td>${f2(p.q)} ${esc(i?i.unit:'')}</td><td>${f2(p.total)}</td><td class="mut">${esc(p.sup||'')}${p.staff?' · '+esc(p.staff):''}${p.img?` <a href="${esc(p.img)}" target="_blank" rel="noopener">📷</a>`:''}${p.imgPath?` <a href="#" data-a="img" data-id="${esc(p.imgPath)}">📷</a>`:''}</td><td style="white-space:nowrap"><button class="btn ghost sm" data-a="editpur" data-id="${p.id}">✏️</button>${ISSTAFF?'':` <button class="btn ghost sm" data-a="delpur" data-id="${p.id}">✕</button>`}</td></tr>`}).join('')}</table>`:'<div class="empty">لا يوجد</div>'}</div>
  <div class="card"><h3>التالف</h3>${ws.length?`<table>${ws.map(w=>{const i=ING(w.ing);return `<tr><td class="mut">${dk(w.t).slice(5)}</td><td>${esc(i?i.name:'—')}</td><td>${f2(w.q)} ${esc(i?i.unit:'')}</td><td class="neg">${f2(w.cost)}</td><td><button class="btn ghost sm" data-a="delwaste" data-id="${w.id}">✕</button></td></tr>`}).join('')}</table>`:'<div class="empty">لا يوجد تالف 👍</div>'}</div>`};

let icat=null;
V.items=()=>{const cats=allCats();if(!icat||!cats.includes(icat))icat=cats[0];const T=+S.settings.target;const ps=S.prods.filter(p=>p.cat===icat);const nor=S.prods.filter(p=>!hasRec(p)).length;
  return `<div class="card"><h3>الأصناف والتسعير <button class="btn sec sm" data-a="prod">+ صنف</button></h3>
  <p class="mut" style="margin-top:0">النسبة = تكلفة المواد من السعر (الهدف ${T}%). الرقم الأخضر = ربح الكوب.${nor?` <b class="wr">${nor} صنف بدون وصفة</b> — افتحه وأضف مكوناته عشان يتحسب ربحه.`:''}</p>
  <div class="row" style="overflow-x:auto;flex-wrap:nowrap;margin-bottom:6px;padding-bottom:4px">${cats.map(c=>`<button class="btn sm ${c===icat?'':'ghost'}" style="flex:0 0 auto" data-a="icat" data-id="${esc(c)}">${esc(c)}</button>`).join('')}</div>
  ${ps.map(p=>{const sz=sizesOf(p),hr=hasRec(p);return `<div style="border-bottom:1px solid var(--line);padding:10px 0"><div class="row"><b data-a="rename" data-id="${p.id}" style="cursor:pointer">${esc(p.name)} <span class="mut" style="font-size:13px">✏️</span></b>${hr?(p.recipe.some(r=>LQ(ING(r.i)))?`<span class="mut">${Math.round(juiceMl(p,'M'))} مل/وسط</span>`:'')+(p.est?'<span class="tag t-w">وصفة تقديرية</span>':''):'<span class="tag t-w">بدون وصفة</span>'}<span class="sp"></span><button class="btn ghost sm" data-a="prod" data-id="${p.id}">${hr?'تعديل':'أضف الوصفة'}</button></div>
   <div class="row" style="margin-top:6px;gap:6px">${sz.map(z=>{const pr=+p.prices[z.id],c=cost(p,z.id),pc=c/pr*100;const cls=pc>T+8?'t-b':pc>T+2?'t-w':'t-ok';return `<div style="background:var(--bg);border-radius:8px;padding:5px 9px;font-size:13px;min-width:74px"><span class="mut">${esc(z.name)}</span> <b>${f2(pr)}</b>${hr&&noCost(p,z.id)?`<div><span class="tag t-w">ناقص أسعار</span></div>`:hr?`<div><span class="tag ${cls}">${Math.round(pc)}%</span> <span class="${pr-c>=0?'pos':'neg'}">${pr-c>=0?'+':''}${f2(pr-c)}</span></div>`:''}</div>`}).join('')}</div></div>`}).join('')}</div>`};

let yf=null,yn=2,yp=null,yc=50,ysz='M';
const szSel=(id,list)=>`<select id="${id}">${list.map(z=>`<option value="${z.id}" ${z.id===ysz?'selected':''}>${esc(z.name)}${z.ml?' ('+z.ml+' مل)':''}</option>`).join('')}</select>`;
let ymode=null;
V.yield=()=>{const fr=S.ings.filter(i=>+i.yield>0&&!['مواد أساسية','ألبان'].includes(i.cat));if(!yf||!ING(yf))yf=(fr.find(i=>i.name==='برتقال')||fr[0]||{}).id;const fi=ING(yf);
  if(fi&&(!ymode||(ymode==='pack'&&!fi.packSize)||(ymode==='pcs'&&(!fi.pcs||fi.unit==='حبة'||fi.pack==='حبة'))))ymode=fi.pcs&&fi.unit!=='حبة'&&fi.pack!=='حبة'?'pcs':fi.packSize?'pack':'unit';
  const withRec=S.prods.filter(hasRec);if(!yp||!PROD(yp))yp=(withRec.find(p=>p.recipe.filter(r=>+(ING(r.i)||{}).yield>0).length>1)||withRec[0]||S.prods[0]||{}).id;
  const p=PROD(yp);const psz=p?sizesOf(p):[];if(p&&!psz.find(z=>z.id===ysz)&&psz.length)ysz=(psz.find(z=>z.id==='M')||psz[0]).id;
  if(!fr.length)return '<div class="card"><div class="empty">حدد عائد العصير للفواكه من صفحة المخزون</div></div>';
  const modes=[['pack',fi.pack||'كرتون',fi.packSize],['pcs','حبة',fi.unit!=='حبة'&&fi.pack!=='حبة'&&fi.pcs],['unit',fi.unit,1]].filter(m=>m[2]);
  return `<div class="card"><h3>🍊 حاسبة العصير</h3>
   <div class="row" style="overflow-x:auto;flex-wrap:nowrap;padding-bottom:4px">${fr.map(i=>`<button class="btn sm ${i.id===yf?'':'ghost'}" style="flex:0 0 auto" data-a="yfr" data-id="${i.id}">${esc(i.name)}</button>`).join('')}</div>
   <div class="row" style="margin-top:12px;gap:8px;font-size:17px"><b>عندي</b><input id="yn" type="number" inputmode="decimal" step="any" min="0" value="${r2(yn*1000)/1000}" style="width:80px;font-size:18px;font-weight:800;text-align:center"><span style="display:inline-flex;border:1px solid var(--line);border-radius:10px;overflow:hidden">${modes.map(([k,l])=>`<button class="btn sm" style="border-radius:0;${k===ymode?'':'background:transparent;color:var(--mut)'}" data-a="ymode" data-id="${k}">${esc(l)}</button>`).join('')}</span><b>${esc(fi.name)}</b></div>${ymode!=='pack'?`<div class="row" style="gap:6px;margin-top:6px"><span class="mut">كسور:</span>${fracBtns('yn')}</div>`:''}
   ${spOf(fi)?'':`<div style="margin-top:8px">${yxHtml()}<button class="btn sec sm" style="margin-top:8px" data-a="yxadd">➕ إضافة (ماء، سكر، ثلج، لب مجمد…)</button></div>`}
   <div id="yA" style="margin-top:14px">${yA()}</div>
   <button class="btn ghost sm" style="margin-top:10px" data-a="measure" data-id="${fi.id}">⚖️ الأرقام مو مضبوطة؟ قِس بنفسك</button></div>
  <details class="card"><summary style="cursor:pointer;font-weight:800">🍹 حاسبة الخلطات (مثل الكوكتيل)</summary><div style="margin-top:10px">
   <div class="two"><div><label>الصنف</label><select id="yp">${allCats().map(c=>`<optgroup label="${esc(c)}">${S.prods.filter(x=>x.cat===c).map(x=>`<option value="${x.id}" ${x.id===yp?'selected':''}>${esc(x.name)}${hasRec(x)?'':' (بدون وصفة)'}</option>`).join('')}</optgroup>`).join('')}</select></div><div><label>المقاس</label>${szSel('ys2',psz)}</div></div>
   <div class="two"><div><label>كم كوب</label><input id="yc" type="number" value="${yc}"></div><div><label>أو كم لتر</label><input id="yl" type="number" step="any" value="${r2(yc*juiceMl(p,ysz)/1000)}"></div></div><div id="yB" style="margin-top:12px">${yB()}</div></div></details>
  <details class="card"><summary style="cursor:pointer;font-weight:800">📦 جدول الفواكه: الكرتون كم لتر وكم يكلف</summary><table style="margin-top:10px"><tr><th>الفاكهة</th><th>الكرتون</th><th>يطلع</th><th>سعر الكرتون</th><th>اللتر يكلف</th><th></th></tr>${fr.map(i=>`<tr><td>${esc(i.name)}</td><td class="mut">${i.packSize?f2(i.packSize)+' '+esc(i.unit):'—'}</td><td><b>${i.packSize?f2(i.packSize*i.yield)+' لتر':'—'}</b></td><td>${i.packSize?f2(i.packSize*i.cost):'—'}</td><td>${f2(i.cost/i.yield)}</td><td><button class="btn ghost sm" data-a="measure" data-id="${i.id}">قِس</button></td></tr>`).join('')}</table></details>`};
let yx=[],ypr=null;
const volOf=i=>i?(+i.yield||+i.vol||(i.unit==='لتر'?1:0)):0;
const modesOf=i=>[['pack',i.pack||'كرتون',i.packSize],['pcs','حبة',i.unit!=='حبة'&&i.pack!=='حبة'&&i.pcs],['unit',i.unit,1]].filter(m=>m[2]);
const qOf=(i,n,m)=>m==='pack'?n*i.packSize:m==='pcs'?n/i.pcs:n;
function spOf(i){return S.prods.find(p=>p.cat==='عصيرات'&&p.lit&&p.recipe.length&&p.recipe[0].i===i.id)||S.prods.find(p=>p.lit&&p.recipe.length&&p.recipe[0].i===i.id)}
function yA(){const i=ING(yf);if(!i)return'';const sp=spOf(i);if(!sp)return yA0();const cur=esc(S.settings.cur);
  const q=qOf(i,yn,ymode),cM=cplP(sp,'M'),lit=sp.recipe.map(r=>({g:ING(r.i),q:r.q*cM})).filter(x=>x.g);const main=lit[0];const Lr=main.q?q/main.q:0;
  const c=lit.reduce((a,x)=>a+x.q*Lr*x.g.cost,0);const zs=sizesOf(sp).filter(z=>['S','M','L'].includes(z.id));
  const fmtQ=(g,v)=>g.unit==='حبة'?fracTxt(v)+' '+esc(g.unit):(g.pcs&&g.pack!=='حبة'&&g.name===i.name?f2(v)+' '+esc(g.unit)+' ('+fracTxt(v*g.pcs)+' حبة)':f2(v)+' '+esc(g.unit));
  const box=z=>{const n=Math.floor(Lr*cplP(sp,z.id)*4+1e-3)/4,cc=cost(sp,z.id),pr=+sp.prices[z.id];return `<div style="flex:1;min-width:92px;background:var(--bg);border-radius:12px;padding:10px;text-align:center"><div class="mut">${esc(z.name)}</div><div style="font-size:24px;font-weight:800">${fracTxt(n)}</div><div class="mut">كوب · تكلفته ${f2(cc)}</div>${pr?`<div style="margin-top:4px;font-size:13px">ربح الكوب <b class="${pr-cc>=0?'pos':'neg'}">${f2(pr-cc)}</b></div>`:''}</div>`};
  const M=zs.find(z=>z.id==='M');let tot='';if(M){const n=Math.floor(Lr*cplP(sp,'M')*4+1e-3)/4,cc=cost(sp,'M'),pr=+sp.prices.M;tot=`<div class="tip" style="margin-top:10px;font-size:15px">لو سويتها كلها <b>وسط</b>: ${fracTxt(n)} كوب × ${f2(pr)} = دخل <b>${C(n*pr)}</b><br>تكلفة الكوب ${f2(cc)} ${cur} ← <b class="${pr-cc>=0?'pos':'neg'}">ربحك ${C(n*(pr-cc))}</b> (${pr?Math.round(cc/pr*100):0}% من السعر تكلفة)</div>`}
  const extra=lit.slice(1);
  return `<div style="background:var(--pri2);border-radius:12px;padding:12px;text-align:center"><div style="font-size:22px;font-weight:800">= ${fracTxt(Math.round(Lr*100)/100)} لتر ${esc(sp.name)}</div><div class="mut" style="margin-top:2px">${fmtQ(main.g,q)}</div>${extra.length?`<div style="margin-top:6px;font-size:14px">تحتاج معها: ${extra.map(x=>`<b>${fmtQ(x.g,x.q*Lr)}</b> ${esc(x.g.name)}`).join(' · ')}</div>`:''}<div style="margin-top:4px">التكلفة <b>${C(c)}</b> · اللتر <b>${C(Lr?c/Lr:0)}</b></div></div>
   <div style="margin:12px 0 6px;font-weight:800">يسوي لك:</div><div class="row" style="gap:8px">${zs.map(box).join('')}</div>${tot}`}
function yA0(){const i=ING(yf);if(!i)return'';const cur=esc(S.settings.cur);
  const lines=[{i,q:qOf(i,yn,ymode)}].concat(yx.map(x=>({i:ING(x.i),q:qOf(ING(x.i)||{},+x.n||0,x.m)})).filter(x=>x.i&&x.q>0));
  const L=lines.reduce((a,x)=>a+x.q*volOf(x.i),0),c=lines.reduce((a,x)=>a+x.q*x.i.cost,0);
  const sp=S.prods.find(p=>p.recipe.some(r=>r.i===i.id)&&p.recipe.filter(x=>volOf(ING(x.i))>0).length===1);
  let pp=sp;if(!pp){if(!ypr||!PROD(ypr)){const k=norm(i.name);ypr=(S.prods.find(p=>p.cat==='عصيرات'&&k.split(' ').some(w=>w.length>2&&norm(p.name).includes(w)))||S.prods.find(p=>p.cat==='عصيرات')||{}).id}pp=PROD(ypr)}
  const zs=(pp?sizesOf(pp):S.sizes).filter(z=>z.ml&&['S','M','L'].includes(z.id));
  const pkg=z=>cost({recipe:[],prices:{}},z.id);
  const mlPer=z=>sp?juiceMl(sp,z.id)||z.ml:z.ml;
  const other=z=>sp?cost(sp,z.id)-sp.recipe.reduce((a,r)=>{const g=ING(r.i);return a+(volOf(g)>0?r.q*fac(z.id)*g.cost:0)},0):pkg(z);
  const cupC=z=>L?c/(L*1000)*mlPer(z)+other(z):0;
  const box=z=>{const n=L?Math.floor(L*1000/mlPer(z)+1e-9):0,cc=cupC(z),pr=pp?+pp.prices[z.id]:0;
    return `<div style="flex:1;min-width:92px;background:var(--bg);border-radius:12px;padding:10px;text-align:center"><div class="mut">${esc(z.name)}</div><div style="font-size:24px;font-weight:800">${n}</div><div class="mut">كوب · تكلفته ${f2(cc)}</div>${pr?`<div style="margin-top:4px;font-size:13px">ربح الكوب <b class="${pr-cc>=0?'pos':'neg'}">${f2(pr-cc)}</b></div>`:''}</div>`};
  const M=zs.find(z=>z.id==='M');let tot='';if(pp&&M&&L){const n=Math.floor(L*1000/mlPer(M)+1e-9),cc=cupC(M),pr=+pp.prices.M;tot=`<div class="tip" style="margin-top:10px;font-size:15px">لو سويتها كلها <b>وسط</b>: ${fracTxt(n)} كوب × ${f2(pr)} = دخل <b>${C(n*pr)}</b><br>تكلفة الكوب ${f2(cc)} ${cur} ← <b class="${pr-cc>=0?'pos':'neg'}">ربحك ${C(n*(pr-cc))}</b> (${pr?Math.round(cc/pr*100):0}% من السعر تكلفة)</div>`}
  const desc=lines.map(x=>`${esc(x.i.name)} ${x.i.unit==='حبة'?fracTxt(x.q):f2(x.q)} ${esc(x.i.unit)}${x.i.pcs&&x.i.unit!=='حبة'&&x.i.pack!=='حبة'?' ('+fracTxt(x.q*x.i.pcs)+' حبة)':''}`).join(' + ');
  const noVol=lines.filter(x=>!volOf(x.i)).map(x=>esc(x.i.name));
  return `<div style="background:var(--pri2);border-radius:12px;padding:12px;text-align:center"><div style="font-size:22px;font-weight:800">= ${f2(L)} لتر</div><div class="mut" style="margin-top:2px">${desc}</div><div style="margin-top:4px">التكلفة <b>${C(c)}</b> · اللتر <b>${C(L?c/L:0)}</b></div>${noVol.length?`<div class="mut" style="font-size:12px">(${noVol.join('، ')} ما تزيد الحجم)</div>`:''}</div>
   <div style="margin:12px 0 6px;font-weight:800">يسوي لك${sp?' ('+esc(sp.name)+')':''}:</div>${!sp?`<div class="row" style="gap:6px;margin-bottom:8px"><span class="mut">احسب الربح على سعر</span><select id="ypr" style="width:auto;padding:5px">${allCats().filter(c=>['عصيرات','خلطات','ملك شيك'].includes(c)).map(c=>`<optgroup label="${esc(c)}">${S.prods.filter(p=>p.cat===c).map(p=>`<option value="${p.id}" ${p.id===ypr?'selected':''}>${esc(p.name)}</option>`).join('')}</optgroup>`).join('')}</select><span class="mut">(كوب ممتلي)</span></div>`:''}<div class="row" style="gap:8px">${zs.map(box).join('')}</div>${tot}`}
function yxHtml(){const opts=sel=>ICATS.filter(c=>!['بلاستيك وتغليف','منظفات'].includes(c)).map(c=>{const g=S.ings.filter(x=>(x.cat||'أخرى')===c);return g.length?`<optgroup label="${c}">${g.map(x=>`<option value="${x.id}" ${x.id===sel?'selected':''}>${esc(x.name)}</option>`).join('')}</optgroup>`:''}).join('');
  return yx.map((x,k)=>{const i=ING(x.i)||{};return `<div class="row" style="gap:6px;margin-top:6px;flex-wrap:nowrap"><b>+</b><input class="yx_n" id="yxn_${k}" data-k="${k}" type="number" inputmode="decimal" step="any" min="0" value="${r2(x.n*1000)/1000}" style="width:64px;padding:6px"><select class="yx_m" data-k="${k}" style="width:auto;padding:6px">${modesOf(i).map(([m,l])=>`<option value="${m}" ${m===x.m?'selected':''}>${esc(l)}</option>`).join('')}</select><select class="yx_i" data-k="${k}" style="padding:6px">${opts(x.i)}</select><button class="btn ghost sm" data-a="yxdel" data-id="${k}">✕</button></div>${x.m!=='pack'?`<div style="margin:2px 22px 0 0">${fracBtns('yxn_'+k)}</div>`:''}`}).join('')}
document.addEventListener('input',e=>{if(e.target.classList.contains('yx_n')){yx[e.target.dataset.k].n=pF(e.target.value)||0;$('#yA').innerHTML=yA()}});
document.addEventListener('change',e=>{if(e.target.id==='ypr'){ypr=e.target.value;$('#yA').innerHTML=yA();return}const k=e.target.dataset.k;if(e.target.classList.contains('yx_i')){const i=ING(e.target.value);yx[k].i=e.target.value;yx[k].m=modesOf(i).find(m=>m[0]==='unit')?'unit':modesOf(i)[0][0];render()}if(e.target.classList.contains('yx_m')){yx[k].m=e.target.value;render()}if(e.target.classList.contains('yx_n'))saveUI()});

function yB(){const p=PROD(yp);if(!p)return'';if(!hasRec(p))return `<div class="alert a-w">«${esc(p.name)}» ما له وصفة. <a href="#items" data-a="prod" data-id="${p.id}">أضف مكوناته</a> (كم مل من كل عصير في الكوب الوسط) وبعدها تطلع لك الحسابات.</div>`;
  const n=yc,ml=juiceMl(p,ysz),pr0=+p.prices[ysz]||0;let tc=0;const use=useOf(p,ysz);
  const rows=use.map(r=>{const i=ING(r.i);if(!i)return'';const q=r.q*n,L=q*LQ(i),c=q*i.cost;tc+=c;const pk=packs(i,q);const pml=r.q*LQ(i)*1000;
    return `<tr><td>${esc(i.name)}${pml?`<div class="mut">${Math.round(pml)} مل/كوب${ml?' · '+Math.round(pml/ml*100)+'%':''}</div>`:''}</td><td>${L?'<b>'+f2(L)+'</b> لتر':'<span class="mut">—</span>'}</td><td>${f2(q)} ${esc(i.unit)}${pk?`<div class="mut">${f2(pk)} ${esc(i.pack)} → اشترِ <b>${Math.ceil(pk)}</b></div>`:''}</td><td>${f2(c)}</td></tr>`}).join('');
  const rev=n*pr0,pr=rev-tc;let cap=Infinity,lim='';use.forEach(r=>{const i=ING(r.i);if(i&&r.q>0){const k=Math.floor(Math.max(0,i.stock)/r.q);if(k<cap){cap=k;lim=i.name}}});
  return `<table><tr><th>المكوّن</th><th>العصير</th><th>الكمية</th><th>التكلفة</th></tr>${rows}</table>
   <div class="kpis" style="margin-top:12px"><div class="kpi"><div class="l">إجمالي الخلطة</div><div class="v">${f2(n*ml/1000)} لتر</div><div class="s">${Math.round(ml)} مل للكوب</div></div><div class="kpi"><div class="l">التكلفة</div><div class="v">${C(tc)}</div><div class="s">${C(n?tc/n:0)} للكوب</div></div><div class="kpi"><div class="l">الدخل (${n} × ${f2(pr0)})</div><div class="v">${C(rev)}</div></div><div class="kpi"><div class="l">الربح</div><div class="v ${pr>=0?'pos':'neg'}">${C(pr)}</div><div class="s">نسبة التكلفة ${rev?Math.round(tc/rev*100):0}% · المقترح ${C(sugPrice(n?tc/n:0))}</div></div></div>
   ${cap!==Infinity?`<div class="tip">📦 من مخزونك الحالي تقدر تسوي <b>${cap}</b> ${esc(vname(p,ysz))} — أول شي يخلص: <b>${esc(lim)}</b></div>`:''}`}
document.addEventListener('input',e=>{const id=e.target.id;if(!['yn','yc','yl'].includes(id))return;
  if(id==='yn'){yn=pF(e.target.value)||0;$('#yA').innerHTML=yA()}
  if(id==='yc'){yc=parseInt(e.target.value)||0;$('#yl').value=r2(yc*juiceMl(PROD(yp),ysz)/1000);$('#yB').innerHTML=yB()}
  if(id==='yl'){const ml=juiceMl(PROD(yp),ysz);yc=ml?Math.round((pF(e.target.value)||0)*1000/ml):0;$('#yc').value=yc;$('#yB').innerHTML=yB()}});
document.addEventListener('change',e=>{const id=e.target.id;if(id==='yn')render();if(id==='yf'){yf=e.target.value;render()}if(id==='yp'){yp=e.target.value;render()}if(id==='ys1'||id==='ys2'){ysz=e.target.value;render()}});

const _measure=id=>{edit=id;const i=ING(id);const cp=i.pcs&&i.packSize?Math.round(i.pcs*i.packSize):'';openM(`<h3>قِس عائد ${esc(i.name)}</h3><p class="mut">اعصر كمية معروفة واكتب كم لتر طلع. تقدر تحسبها <b>بالحبة</b> أو <b>بالوزن</b>.</p>
  <div class="tip"><b>بالحبة</b><div class="two"><div><label>كم حبة عصرت</label><input id="m_pc" type="number" step="any" placeholder="مثلاً 14"></div><div><label>كم لتر طلع</label><input id="m_l" type="number" step="any" placeholder="مثلاً 1"></div></div></div>
  <div class="tip"><b>أو بالوزن</b><label>كم ${esc(i.unit)} عصرت</label><input id="m_q" type="number" step="any"></div>
  <div class="two"><div><label>كم ${esc(i.unit)} في ال${esc(i.pack||'كرتون')}</label><input id="m_ps" type="number" step="any" value="${i.packSize||''}"></div><div><label>كم حبة تقريباً في ال${esc(i.pack||'كرتون')}</label><input id="m_cp" type="number" step="any" value="${cp}"></div></div>
  <div class="tip" style="margin-top:10px" id="m_r">${mRes(i)}</div>${foot('savemeasure')}`)};
function mCalc(i){const pc=num('m_pc'),l=num('m_l'),q=num('m_q'),ps=num('m_ps')||i.packSize,cp=num('m_cp');const pcs=cp&&ps?cp/ps:(+i.pcs||0);let y=null;if(l&&pc&&pcs)y=l/(pc/pcs);else if(l&&q)y=l/q;return{y,pcs,ps,cp,pc,l}}
function mRes(i,c){c=c||{y:i.yield,pcs:+i.pcs||0,ps:i.packSize};const y=c.y||i.yield;if(!y)return'اكتب الأرقام عشان يطلع العائد';const perL=c.pcs?1/y*c.pcs:0;
  const ps=S.prods.filter(p=>p.recipe.some(r=>r.i===i.id)&&p.recipe.filter(x=>+(ING(x.i)||{}).yield>0).length===1);const drink=S.sizes.filter(z=>z.ml);
  return `${c.y&&c.y!==i.yield?'العائد الجديد':'العائد'}: <b>${f2(y)}</b> لتر لكل ${esc(i.unit)}${perL?` · <b>اللتر ≈ ${f2(perL)} حبة</b>`:''}${c.ps?` · ال${esc(i.pack||'كرتون')} ≈ <b>${f2(c.ps*y)} لتر</b>`:''}${ps.length?`<div style="margin-top:6px">من اللتر الواحد: ${drink.map(z=>{const ml=juiceMl(ps[0],z.id);return ml?`${esc(z.name)} <b>${f2(Math.floor(1000/ml*10)/10)}</b>`:''}).filter(Boolean).join(' · ')}</div>`:''}`}
document.addEventListener('input',e=>{if(['m_pc','m_l','m_q','m_ps','m_cp'].includes(e.target.id)){const i=ING(edit);$('#m_r').innerHTML=mRes(i,mCalc(i))}});
const _savemeasure=()=>{const i=ING(edit),c=mCalc(i);if(c.y)i.yield=Math.round(c.y*1000)/1000;if(num('m_ps'))i.packSize=num('m_ps');if(c.cp&&i.packSize)i.pcs=c.cp/i.packSize;if(!i.pack)i.pack='كرتون';closeM();save('✓ تم تحديث العائد');render()};

V.budget=()=>{const m=month();const bp=S.settings.budget?Math.min(100,m.pur/S.settings.budget*100):0;const ex=inRange(S.expenses,mStart());const paid={};ex.forEach(e=>paid[e.cat]=(paid[e.cat]||0)+e.amount);const be=breakEven();
  const exp=S.expenses.slice().sort((a,b)=>b.t-a.t).slice(0,20);
  return `<div class="card"><h3>ميزانية المقاضي — ${MONTHS[new Date().getMonth()]} <button class="btn ghost sm" data-go="prefs">تغيير</button></h3><div class="row"><span>صرفت ${C(m.pur)}</span><span class="sp"></span><span class="mut">من ${C(S.settings.budget)}</span></div><div class="bar" style="margin:6px 0"><i style="width:${bp}%;background:${bp>90?'var(--bad)':bp>70?'var(--warn)':'var(--pri)'}"></i></div>
   <div class="mut">المفروض بهذا اليوم من الشهر تكون صارف تقريباً ${C(S.settings.budget*m.dayN/dim())}</div>
   </div>
  <div class="card"><h3>المصاريف الثابتة الشهرية <button class="btn sec sm" data-a="fixed">+ بند</button></h3><table><tr><th>البند</th><th>المخطط</th><th>المدفوع</th><th></th></tr>${S.fixed.map(f=>`<tr><td>${esc(f.name)}</td><td>${f2(f.amount)}</td><td>${paid[f.name]?`<span class="tag ${paid[f.name]>f.amount?'t-b':'t-ok'}">${f2(paid[f.name])}</span>`:'<span class="mut">—</span>'}</td><td><button class="btn ghost sm" data-a="fixed" data-id="${f.id}">تعديل</button></td></tr>`).join('')}<tr><td><b>الإجمالي</b></td><td><b>${f2(fixedTotal())}</b></td><td></td><td></td></tr></table>
   <p class="mut">= ${C(fixedTotal()/30)} يومياً. نقطة التعادل: <b>${be.cups} كوب/يوم</b> بمتوسط ربح ${C(be.m.avgMargin)} للكوب.</p></div>
  <div class="card"><h3>سجل المصاريف <button class="btn sec sm" data-a="exp">+ مصروف</button></h3>${exp.length?`<table>${exp.map(e=>`<tr><td class="mut">${dk(e.t).slice(5)}</td><td>${esc(e.cat)}</td><td class="mut">${esc(e.note||'')}</td><td>${f2(e.amount)}</td><td><button class="btn ghost sm" data-a="delexp" data-id="${e.id}">✕</button></td></tr>`).join('')}</table>`:'<div class="empty">لا يوجد</div>'}</div>`};

V.reports=()=>{const today=sod(Date.now());const days=[];for(let d=13;d>=0;d--){const f=today-d*DAY;const s=salesSum(inRange(S.sales,f,f+DAY));days.push({f,...s})}const mx=Math.max(1,...days.map(d=>d.rev));
  const by={};inRange(S.sales,today-13*DAY).forEach(s=>s.items.forEach(i=>{const o=by[i.n]=by[i.n]||{q:0,rev:0,pr:0};o.q+=i.q;o.rev+=i.price*i.q;o.pr+=(i.price-i.cost)*i.q}));const arr=Object.entries(by).sort((a,b)=>b[1].pr-a[1].pr);const mq=Math.max(1,...arr.map(a=>a[1].pr));
  const hrs=Array(24).fill(0);inRange(S.sales,today-13*DAY).forEach(s=>hrs[new Date(s.t).getHours()]+=s.total);const hmin=hrs.findIndex(x=>x>0),hmax=23-hrs.slice().reverse().findIndex(x=>x>0);const hm=Math.max(1,...hrs);
  const pays={};inRange(S.sales,today-13*DAY).forEach(s=>pays[s.pay]=(pays[s.pay]||0)+s.total);const tot=days.reduce((a,b)=>a+b.rev,0);
  const wd=['أحد','إثنين','ثلاثاء','أربعاء','خميس','جمعة','سبت'];
  return `<div class="kpis"><div class="kpi"><div class="l">مبيعات 14 يوم</div><div class="v">${C(tot)}</div></div><div class="kpi"><div class="l">متوسط يومي</div><div class="v">${C(tot/14)}</div></div><div class="kpi"><div class="l">متوسط الطلب</div><div class="v">${C(tot/Math.max(1,days.reduce((a,b)=>a+b.orders,0)))}</div></div><div class="kpi"><div class="l">الدفع</div><div class="v" style="font-size:15px">${Object.entries(pays).map(([k,v])=>k+' '+Math.round(v/Math.max(1,tot)*100)+'%').join(' · ')||'—'}</div></div></div>
  <div class="card"><h3>المبيعات اليومية (آخر 14 يوم)</h3><div class="chart">${days.map(d=>`<div title="${f2(d.rev)}"><span>${Math.round(d.rev)}</span><i style="height:${d.rev/mx*100}%"></i><span>${new Date(d.f).getDate()}</span></div>`).join('')}</div></div>
  <div class="card"><h3>الأصناف حسب الربح</h3><table><tr><th>الصنف</th><th>الكمية</th><th>المبيعات</th><th>الربح</th></tr>${arr.map(([n,o])=>`<tr><td>${esc(n)}<div class="bar" style="margin-top:4px"><i style="width:${o.pr/mq*100}%"></i></div></td><td>${o.q}</td><td>${f2(o.rev)}</td><td class="pos">${f2(o.pr)}</td></tr>`).join('')}</table></div>
  ${hmin>=0?`<div class="card"><h3>أوقات الذروة</h3><div class="chart">${hrs.slice(hmin,hmax+1).map((v,k)=>`<div><i style="height:${v/hm*100}%;background:var(--acc)"></i><span>${(hmin+k)%12||12}</span></div>`).join('')}</div></div>`:''}`};

V.prefs=()=>{const s=S.settings;return `<div class="card"><h3>إعدادات المحل</h3>
  <label>شعار المحل (اللوجو)</label><div class="row">${S.settings.logo?`<img src="${S.settings.logo}" style="width:56px;height:56px;border-radius:12px;object-fit:contain;background:#fff;border:1px solid var(--line)">`:''}<input type="file" id="p_logo" accept="image/*" style="flex:1">${S.settings.logo?'<button class="btn ghost sm" data-a="dellogo">حذف</button>':''}</div>
  <label>اسم المحل</label><input id="p_shop" value="${esc(s.shop)}"><div class="two"><div><label>العملة</label><input id="p_cur" value="${esc(s.cur)}"></div><div><label>ميزانية المقاضي الشهرية</label><input id="p_budget" type="number" value="${s.budget}"></div></div>
  <div class="two"><div><label>نسبة التكلفة المستهدفة %</label><input id="p_target" type="number" value="${s.target}"></div><div><label>اشترِ مقاضي تكفي (أيام)</label><input id="p_cover" type="number" value="${s.cover}"></div></div>
  <label style="display:flex;gap:8px;align-items:center;margin-top:14px;color:var(--ink)"><input type="checkbox" id="p_simple" style="width:auto" ${S.settings.simple===false?'':'checked'}> الوضع البسيط (إخفاء الصفحات تحت «المزيد»)</label>
  <button class="btn full" style="margin-top:14px" data-a="saveprefs">حفظ</button></div>
  <div class="card"><h3>المقاسات</h3><p class="mut" style="margin-top:0">الوصفات مكتوبة لمقاس <b>وسط</b>، وباقي المقاسات تتحسب تلقائياً حسب الحجم بالمل. والتغليف (كوب، شفاط، قارورة) ينخصم حبة وحدة مع كل طلب.</p>
  <table><tr><th>المقاس</th><th>حجم الكوب (مل)</th><th>العصير الفعلي (مل)</th><th>التغليف</th></tr>${S.sizes.map(z=>`<tr><td><input class="sz_n" data-s="${z.id}" value="${esc(z.name)}"></td><td style="width:80px">${z.ml||z.id==='M'?`<input class="sz_ml" data-s="${z.id}" type="number" value="${z.ml}">`:'<span class="mut">حصة</span>'}</td><td style="width:80px">${z.ml?`<input class="sz_j" data-s="${z.id}" type="number" value="${Math.round(+z.jml||z.ml)}">`:''}</td><td>${[0,1].map(j=>`<select class="sz_pk" data-s="${z.id}" data-j="${j}"><option value="">—</option>${S.ings.map(i=>`<option value="${i.id}" ${(z.pk||[])[j]===i.id?'selected':''}>${esc(i.name)}</option>`).join('')}</select>`).join('')}</td></tr>`).join('')}</table>
  <button class="btn full sec" style="margin-top:12px" data-a="savesizes">حفظ المقاسات</button></div>
  ${staffCard()}<div class="card"><h3>البيانات</h3>${S.demo?'<button class="btn full red" data-a="cleardemo">🧹 مسح البيانات التجريبية (المبيعات والمشتريات والمصاريف)</button><p class="mut">تبقى المواد والأصناف عشان تعدلها لمحلك.</p>':''}
   <div class="row" style="margin-top:8px"><button class="btn sec sp" data-a="export">نسخ احتياطي</button><button class="btn sec sp" data-a="import">استرجاع نسخة</button></div>
   <p class="mut">البيانات تنحفظ تلقائياً في الصفحة بعد كل عملية، ونسخة احتياطية تلقائية لآخر 3 أيام على هذا الجهاز:</p>${(()=>{let ks=[];try{ks=Object.keys(localStorage).filter(x=>x.startsWith('juice_bk_')).sort().reverse()}catch(e){}return ks.length?ks.map(k=>`<div class="row" style="margin-top:4px"><span>📦 ${k.slice(9)}</span><span class="sp"></span><button class="btn ghost sm" data-a="bkrestore" data-id="${k}">استرجاع</button></div>`).join(''):'<p class="mut">ما فيه نسخ لسه.</p>'})()}</div>`};

/* ---------- النوافذ ---------- */
function openM(html){const m=$('#modal');m.querySelector('.box').innerHTML=html;m.classList.add('on');const f=m.querySelector('input,select');if(f)setTimeout(()=>f.focus(),50)}
function closeM(){$('#modal').classList.remove('on')}
const val=id=>{const e=document.getElementById(id);return e?e.value.trim():''};const num=id=>pF(val(id))||0;
const ingOpts=sel=>S.ings.map(i=>`<option value="${i.id}" ${i.id===sel?'selected':''}>${esc(i.name)} (${esc(i.unit)})</option>`).join('');
const foot=(a,del)=>`<div class="row" style="margin-top:16px">${del?`<button class="btn red" data-a="${del}">حذف</button>`:''}<span class="sp"></span><button class="btn ghost" data-a="close">إلغاء</button><button class="btn" data-a="${a}">حفظ</button></div>`;
function ask(msg,fn){openM(`<h3>${msg}</h3><div class="row" style="margin-top:16px"><span class="sp"></span><button class="btn ghost" data-a="close">لا</button><button class="btn red" data-a="yes">نعم</button></div>`);A.yes=()=>{closeM();fn()}}
let edit=null;

const A={close:closeM,savesizes:()=>{S.sizes.forEach(z=>{const n=document.querySelector(`.sz_n[data-s="${z.id}"]`),m=document.querySelector(`.sz_ml[data-s="${z.id}"]`);if(n&&n.value.trim())z.name=n.value.trim();if(m)z.ml=toNum(m.value)||z.ml;const jj=document.querySelector(`.sz_j[data-s="${z.id}"]`);if(jj)z.jml=toNum(jj.value)||z.ml;z.pk=[0,1].map(j=>document.querySelector(`.sz_pk[data-s="${z.id}"][data-j="${j}"]`).value).filter(Boolean)});save('تم حفظ المقاسات');render()},measure:_measure,savemeasure:_savemeasure};
A.add=id=>{cart[id]=(cart[id]||0)+1;render()};A.dec=id=>{cart[id]=Math.max(0,(cart[id]||0)-1);render()};A.clr=()=>{cart={};render()};A.pay=p=>{pay=p;render()};
A.scat=c=>{scat=c;render()};A.icat=c=>{icat=c;render()};
A.pick=id=>{const p=PROD(id);const sz=sizesOf(p);if(sz.length===1){const k=p.id+'|'+sz[0].id;cart[k]=(cart[k]||0)+1;return render()}
  openM(`<h3>${esc(p.name)}</h3><div class="grid">${sz.map(z=>`<button class="pbtn" data-a="addsz" data-id="${p.id}|${z.id}"><b>${esc(z.name)}</b><span>${C(p.prices[z.id])}</span></button>`).join('')}</div><div class="row" style="margin-top:12px"><span class="sp"></span><button class="btn ghost" data-a="close">إلغاء</button></div>`)};
A.addsz=k=>{cart[k]=(cart[k]||0)+1;closeM();render();toast('أضيف '+vname(PROD(k.split('|')[0]),k.split('|')[1]))};
A.checkout=()=>{const items=Object.entries(cart).filter(([,q])=>q>0).map(([k,q])=>{const [pid,sid]=k.split('|');const p=PROD(pid);return p&&{p:pid,s:sid,n:vname(p,sid),q,price:+p.prices[sid],cost:r2(cost(p,sid))}}).filter(Boolean);if(!items.length)return;
  items.forEach(it=>deduct(it.p,it.s,it.q,1));
  const total=items.reduce((s,i)=>s+i.price*i.q,0);S.sales.push({id:uid(),t:Date.now(),items,pay,total});cart={};save('✓ تم تسجيل '+f2(total));render()};
A.delsale=id=>ask('حذف هذا الطلب وإرجاع المواد للمخزون؟',()=>{const s=S.sales.find(x=>x.id===id);if(!s)return;s.items.forEach(it=>it.s&&deduct(it.p,it.s,it.q,-1));S.sales=S.sales.filter(x=>x.id!==id);save('تم الحذف');render()});

A.buy=id=>{const n=id?(needList().list.find(x=>x.i.id===id)||needs().find(x=>x.i.id===id)):null;openM(`<h3>🛒 تسجيل مشتريات</h3><label>المادة</label><select id="b_ing">${ingOpts(id)}</select><div class="two"><div><label>الكمية</label><input id="b_q" type="number" step="any" value="${n?n.buy:''}"></div><div><label>المبلغ الإجمالي المدفوع</label><input id="b_t" type="number" step="any" value="${n?r2(n.est):''}"></div></div><div id="b_pkw">${pkw(id||S.ings[0]?.id)}</div><div class="two"><div><label>تاريخ الشراء</label><input id="b_d" type="date" value="${dk(Date.now())}"></div><div><label>المورد (اختياري)</label><input id="b_s" list="sups"><datalist id="sups">${[...new Set(S.purchases.map(p=>p.sup).filter(Boolean))].map(s=>`<option value="${esc(s)}">`).join('')}</datalist></div></div>${window.CLOUD?'<label>📷 صورة الفاتورة (اختياري)</label><input type="file" id="b_img" accept="image/*"><div id="b_imgst" class="mut"></div>':''}${foot('savebuy')}`);BIMG=null;if(n&&inPack(n.i)){const e=$('#b_pn');if(e){e.value=Math.ceil(n.buy/n.i.packSize);e.dispatchEvent(new Event('input',{bubbles:true}))}}};
function pkw(id){const i=ING(id);if(!i||!i.packSize)return'';return `<div class="two"><div><label>أو عدد ال${esc(i.pack)} (${f2(i.packSize)} ${esc(i.unit)})</label><input id="b_pn" type="number" step="any"></div><div><label>سعر ال${esc(i.pack)} الواحد</label><input id="b_pp" type="number" step="any" value="${r2(i.cost*i.packSize)}"></div></div>`}
document.addEventListener('change',e=>{if(e.target.id==='b_ing')$('#b_pkw').innerHTML=pkw(e.target.value)});
document.addEventListener('input',e=>{if(e.target.id==='b_pn'||e.target.id==='b_pp'){const i=ING(val('b_ing'));const n=num('b_pn');if(i&&n){$('#b_q').value=r2(n*i.packSize);if(num('b_pp'))$('#b_t').value=r2(n*num('b_pp'))}}});
A.savebuy=()=>{if(BIMG&&BIMG.busy)return toast('لحظة، الصورة تترفع…');const i=ING(val('b_ing')),q=num('b_q'),t=num('b_t');if(!i||q<=0||t<0)return toast('أدخل الكمية والمبلغ');const old=Math.max(0,i.stock);i.cost=r2((old*i.cost+t)/(old+q))||i.cost;i.stock=r2(i.stock+q);i.stockAt=Date.now();i.trk=true;resetCover(i,q,Date.now());const bd=val('b_d');const bt=!bd||bd===dk(Date.now())?Date.now():new Date(bd+'T12:00').getTime();S.purchases.push({id:uid(),t:bt,ing:i.id,q,total:t,sup:val('b_s'),staff:window.CLOUD?CLOUD.userName:'',imgPath:BIMG&&BIMG.path||''});S.extraList=(S.extraList||[]).filter(e=>e.i!==i.id);closeM();save('✓ أضيف للمخزون');render()};
let EP={};
A.editpur=id=>{const p=S.purchases.find(x=>x.id===id);if(!p)return;const i=ING(p.ing);EP={id,k:i&&(i.unit==='كرتون'||inPack(i))?'pack':'unit'};
  EP.html=(q,v,d,ing)=>{const ii=ING(ing)||i;const uN=!ii||!ii.unit||ii.unit==='كجم'?'كيلو':ii.unit;const pN=ii&&ii.pack||'كرتون';const ps=ii&&+ii.packSize>0;
   return `<h3>✏️ تعديل شراء: ${esc(i?i.name:'—')}</h3>
   <label>المادة</label><select id="ep_i">${S.ings.map(x=>`<option value="${x.id}" ${x.id===ing?'selected':''}>${esc(x.name)}</option>`).join('')}</select>
   <div class="row" style="margin-top:12px">${(ii&&ii.unit==='كرتون'?[['pack','كرتون']]:[['unit',uN],['pack',pN]]).map(([k,l])=>`<button type="button" class="btn sp ${k===EP.k?'':'ghost'}" data-a="epk" data-id="${k}">${esc(l)}</button>`).join('')}</div>
   <label>كم ${esc(EP.k==='pack'?pN:uN)}؟</label><input id="ep_q" type="number" inputmode="decimal" value="${q}">
   ${EP.k==='pack'&&!ps&&ii&&ii.unit!=='كرتون'?`<label>ال${esc(pN)} فيه كم ${esc(uN)}؟</label><input id="ep_ps" type="number" inputmode="decimal" placeholder="مثلاً 10">`:''}
   <label>السعر (المبلغ كامل)</label><input id="ep_v" type="number" inputmode="decimal" value="${v}">
   <label>التاريخ</label><input id="ep_d" type="date" value="${d}" max="${dk(Date.now())}">
   <div class="row" style="margin-top:16px">${ISSTAFF?'':`<button class="btn red" data-a="delpur" data-id="${p.id}">حذف</button>`}<span class="sp"></span><button class="btn ghost" data-a="close">إلغاء</button><button class="btn" data-a="saveeditpur" data-id="${p.id}">حفظ</button></div>`};
  const q0=EP.k==='pack'&&i&&+i.packSize>0?r2(p.q/i.packSize):r2(p.q);openM(EP.html(q0,r2(+p.total||0),dk(p.t),p.ing))};
A.epk=k=>{if(EP.k===k)return;const ing=val('ep_i'),ii=ING(ing);let q=num('ep_q');const ps=ii&&+ii.packSize>0?+ii.packSize:0;if(ps&&ii.unit!=='كرتون'&&q>0)q=k==='pack'?r2(q/ps):r2(q*ps);EP.k=k;openM(EP.html(q||'',$('#ep_v').value,$('#ep_d').value,ing))};
A.saveeditpur=id=>{const p=S.purchases.find(x=>x.id===id);if(!p)return;const ni=ING(val('ep_i'))||ING(p.ing);let q=num('ep_q');const v=num('ep_v');if(!(q>0))return toast('اكتب الكمية');
  if(EP.k==='pack'&&ni&&ni.unit!=='كرتون'){let ps=+ni.packSize;if(!(ps>0)){ps=num('ep_ps');if(!(ps>0))return toast('اكتب الكرتون فيه كم');ni.packSize=ps;if(!ni.pack)ni.pack='كرتون'}q=q*ps}
  const d=val('ep_d');const ch={id,ing:ni?ni.id:p.ing,q:r2(q),total:v,t:d&&d!==dk(p.t)?new Date(d+'T12:00').getTime():p.t,by:window.CLOUD?CLOUD.userName:''};if(EP.k==='pack'&&ni&&+ni.packSize>0)ch.ps=+ni.packSize;pEdit(ch);
  closeM();if(ISSTAFF){CLOUD.sendAction({pedit:[ch]}).then(()=>toast('✓ انرسلت للمالك')).catch(()=>toast('⚠️ ما انرسلت، تأكد من النت'));render()}else{save('✓ تعدّل');render()}};
function pEdit(ch){const p=S.purchases.find(x=>x.id===ch.id);if(!p)return 0;const oi=ING(p.ing),ni=ING(ch.ing)||oi;if(ch.ps&&ni&&!(+ni.packSize>0)){ni.packSize=ch.ps;if(!ni.pack)ni.pack='كرتون'}if(oi)oi.stock=r2(oi.stock-p.q);if(ni)ni.stock=r2(ni.stock+ch.q);
  const dq=ch.q-p.q;if(ni&&ni===oi&&+ni.drate>0&&+ni.until>0)ni.until=Math.max(sod(p.t),ni.until+dq/ni.drate*DAY);p.q=ch.q;p.total=ch.total;p.ing=ni?ni.id:p.ing;p.t=ch.t;if(ch.by)p.editBy=ch.by;
  [oi,ni].forEach(i=>{if(!i)return;const lp=S.purchases.filter(x=>x.ing===i.id&&x.q>0&&x.total>0).sort((a,b)=>b.t-a.t)[0];if(lp)i.cost=r2(lp.total/lp.q)});return 1}
A.delpur=id=>ask('حذف هذه العملية وخصم الكمية من المخزون؟',()=>{const p=S.purchases.find(x=>x.id===id);const i=p&&ING(p.ing);if(i)i.stock=r2(i.stock-p.q);S.purchases=S.purchases.filter(x=>x.id!==id);save('تم الحذف');render()});
A.waste=()=>openM(`<h3>🗑️ تسجيل تالف</h3><label>المادة</label><select id="w_ing">${ingOpts()}</select><label>الكمية التالفة</label><input id="w_q" type="number" step="any">${foot('savewaste')}`);
A.savewaste=()=>{const i=ING(val('w_ing')),q=num('w_q');if(!i||q<=0)return;i.stock=r2(i.stock-q);S.waste.push({id:uid(),t:Date.now(),ing:i.id,q,cost:r2(q*i.cost)});closeM();save('تم التسجيل');render()};
A.delwaste=id=>{const w=S.waste.find(x=>x.id===id);const i=w&&ING(w.ing);if(i)i.stock=r2(i.stock+w.q);S.waste=S.waste.filter(x=>x.id!==id);save();render()};

let IU='unit';
function stLevel(i,U){if(!(i.stock>0))return't-b';const now=Date.now();if(+i.until>0){if(now>=i.until)return't-b';if(i.until-now<=DAY)return't-w'}const d=(U||usage())[i.id]||0;if(d>0&&i.stock/d<=1)return't-w';if(i.min>0&&i.stock<=i.min)return't-w';return't-ok'}
let QB={};
// بعد الشراء: كم يوم يكفي = (الباقي المتوقع + اللي انشرى) ÷ الاستهلاك اليومي
function resetCover(i,q,t){if(!(+i.cv>0)){i.until=0;return}const d0=sod(t);let r=+i.drate||0;
  if(!(r>0)){i.until=d0+i.cv*DAY;i.cvQ=i.stock;return}
  const left=+i.until>d0?(i.until-d0)/DAY*r:0;i.until=d0+Math.max(0,left+q)/r*DAY;i.cvQ=i.stock}
