/* ---------- استيراد من الكاشير ---------- */
const AD=t=>String(t??'').replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d));
const toNum=v=>{if(typeof v==='number')return v;const t=AD(v).replace(/[,٬\s]/g,'').replace('٫','.').replace(/[^\d.\-]/g,'');return parseFloat(t)||0};
const norm=t=>AD(t).toLowerCase().replace(/[ً-ْ]/g,'').replace(/[أإآ]/g,'ا').replace(/ة/g,'ه').replace(/ى/g,'ي').replace(/\s+/g,' ').trim();
function toDate(v,fb){if(v instanceof Date&&!isNaN(v))return v.getTime();if(typeof v==='number'&&v>20000&&v<80000)return Math.round((v-25569)*DAY+new Date().getTimezoneOffset()*6e4);
  const t=AD(v).trim();if(!t)return fb;let m=t.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})(?:[ T]+(\d{1,2}):(\d{2})(?::\d{2})?\s*(am|pm|ص|م)?)?/i);
  if(m){let h=+(m[4]||12);const ap=(m[6]||'').toLowerCase();if((ap==='pm'||ap==='م')&&h<12)h+=12;if((ap==='am'||ap==='ص')&&h===12)h=0;return new Date(+m[3],+m[2]-1,+m[1],h,+(m[5]||0)).getTime()}
  const p=Date.parse(t.replace(' ','T'));return isNaN(p)?(Date.parse(t)||fb):p}
