  const never=S.prods.filter(p=>!by[p.id]).length;if(daysData>=14&&never>5)add('w',['menu'],`<b>${never} صنف</b> ما انباع ولا مرة في آخر 30 يوم. المنيو فيه ${S.prods.length} صنف، وهذا كثير على محل عصير. كل صنف زيادة يعني مواد أكثر في المخزون، وخطر تلف أعلى، وموظف أبطأ.`);
