let tvp=30,tvc='الكل';
const dayT=t=>new Date(dk(t)+'T12:00').getTime();
function ivOf(list){const d=[...new Set(list.map(p=>dk(p.t)))].sort().map(x=>new Date(x+'T12:00').getTime());return d.length>=2?(d[d.length-1]-d[0])/DAY/(d.length-1):null}
function tvStats(days){const from=sod(Date.now())-(days-1)*DAY;const ps=inRange(S.purchases,from),prev=inRange(S.purchases,from-days*DAY,from);const it={},cat={};
  S.ings.forEach(i=>{const all=S.purchases.filter(p=>p.ing===i.id).sort((a,b)=>a.t-b.t);if(!all.length){if(+i.every>0)it[i.id]={i,n:0,nAll:0,iv:null,spent:0,prevS:0,last:null,next:null,avgQ:+i.everyQ||0,unitAvg:i.cost,unitLast:i.cost,plan:+i.every};return}const inP=ps.filter(p=>p.ing===i.id);const iv=ivOf(all);const last=all[all.length-1];
    const tq=all.reduce((a,p)=>a+p.q,0),tt=all.reduce((a,p)=>a+p.total,0);
    it[i.id]={i,plan:+i.every||0,n:inP.length,nAll:all.length,iv,spent:inP.reduce((a,p)=>a+p.total,0),prevS:prev.filter(p=>p.ing===i.id).reduce((a,p)=>a+p.total,0),last,next:+i.every>0?dayT(last.t)+i.every*DAY:iv?dayT(last.t)+iv*DAY:null,avgQ:tq/all.length,unitAvg:tq?tt/tq:0,unitLast:last.q?last.total/last.q:0}});
  ICATS.forEach(c=>{const all=S.purchases.filter(p=>((ING(p.ing)||{}).cat||'أخرى')===c);if(!all.length)return;const inP=ps.filter(p=>((ING(p.ing)||{}).cat||'أخرى')===c);
    cat[c]={n:inP.length,spent:inP.reduce((a,p)=>a+p.total,0),prevS:prev.filter(p=>((ING(p.ing)||{}).cat||'أخرى')===c).reduce((a,p)=>a+p.total,0),iv:ivOf(all),last:Math.max(...all.map(p=>p.t))}});
  return{it,cat,rev:salesSum(inRange(S.sales,from)).rev,tot:ps.reduce((a,p)=>a+p.total,0),prev:prev.reduce((a,p)=>a+p.total,0)}}
const ago=t=>{const d=Math.round((sod(Date.now())-sod(t))/DAY);return d<=0?'اليوم':d===1?'أمس':'قبل '+d+' يوم'};
const chg=(a,b)=>b>0?`<span class="${a>b*1.1?'neg':a<b*.9?'pos':'mut'}">${a>=b?'▲':'▼'} ${Math.abs(Math.round((a/b-1)*100))}%</span>`:'<span class="mut">—</span>';
function nextTag(x){if(!x.next)return x.plan&&!x.last?'<span class="tag t-w">ما انشرى لسه</span>':'<span class="mut">يحتاج شراءين</span>';const d=Math.round((x.next-dayT(Date.now()))/DAY);return d<0?`<span class="tag t-b">متأخر ${-d} يوم</span>`:d===0?'<span class="tag t-w">اليوم</span>':d<=2?`<span class="tag t-w">بعد ${d} يوم</span>`:`<span class="tag t-ok">بعد ${d} يوم</span>`}
