A.rename=id=>{edit=id;const p=PROD(id);openM(`<h3>تعديل اسم الصنف</h3><label>الاسم</label><input id="rn_n" value="${esc(p.name)}"><label>القسم</label><input id="rn_c" list="catl2" value="${esc(p.cat)}"><datalist id="catl2">${allCats().map(c=>`<option value="${esc(c)}">`).join('')}</datalist><p class="mut">المبيعات القديمة تبقى بالاسم القديم في السجل.</p>${foot('saverename')}`)};
