/* ---------- الوضع البسيط ---------- */
function quickHome(){const t0=sod(Date.now());const sold=inRange(S.sales,t0).length>0,bought=inRange(S.purchases,t0).length>0;const nb=needs().filter(x=>x.buy>0).length;
  const B=(ic,l,sub,a,go)=>`<button class="pbtn" style="padding:16px 8px" ${go?`data-go="${go}"`:`data-a="${a}"`}><div style="font-size:30px">${ic}</div><b style="font-size:16px">${l}</b><span>${sub}</span></button>`;
  return `<div class="grid" style="margin-bottom:12px">${B('📥','مبيعات اليوم',sold?'✅ مسجلة':'⏳ ما انسجلت','salesin')}${B('🛒','وش أشتري',nb?nb+' مادة':'✅ ما تحتاج','',`needs`)}${B('🧾','سجّل شراء',bought?'✅ سجلت اليوم':'من الفاتورة','buymenu')}${B('💰','سجّل مصروف','إيجار، كهرباء…','exp')}</div>`}
/* ---------- فلتر الرئيسية ---------- */
let hp='day',hd=Date.now();
const WD=['الأحد','الإثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'];
function pRange(kind,anchor){const d=new Date(sod(anchor));let a,b;if(kind==='day'){a=d.getTime();b=a+DAY}else if(kind==='week'){a=d.getTime()-d.getDay()*DAY;b=a+7*DAY}else{a=new Date(d.getFullYear(),d.getMonth(),1).getTime();b=new Date(d.getFullYear(),d.getMonth()+1,1).getTime()}return[a,b]}
function pLabel(kind,a,b){const A=new Date(a),B=new Date(b-DAY);if(kind==='day')return WD[A.getDay()]+' '+A.getDate()+' '+MONTHS[A.getMonth()];if(kind==='week')return A.getDate()+(A.getMonth()!==B.getMonth()?' '+MONTHS[A.getMonth()]:'')+' – '+B.getDate()+' '+MONTHS[B.getMonth()];return MONTHS[A.getMonth()]+' '+A.getFullYear()}
function pStats(a,b){const sl=inRange(S.sales,a,b),s=salesSum(sl);const pur=inRange(S.purchases,a,b).reduce((x,p)=>x+p.total,0),wst=inRange(S.waste,a,b).reduce((x,w)=>x+w.cost,0),exp=inRange(S.expenses,a,b).reduce((x,e)=>x+e.amount,0);
  const days=Math.max(0,Math.min(b,sod(Date.now())+DAY)-a)/DAY;const fx=fixedTotal()/30*days;return{...s,sl,pur,wst,exp,days,fx,gross:s.rev-s.cogs,net:s.rev-s.cogs-wst-fx}}
const dlt=(a,b,inv)=>{if(!b)return'';const p=Math.round((a/b-1)*100);const good=inv?p<=0:p>=0;return `<span class="${good?'pos':'neg'}">${p>=0?'▲':'▼'} ${Math.abs(p)}%</span>`};
const missN=()=>S.ings.filter(i=>!(+i.cost>0)&&(S.prods.some(p=>p.recipe.some(r=>r.i===i.id))||S.sizes.some(z=>(z.pk||[]).includes(i.id)))).length;
function homePeriod(){const [a,b]=pRange(hp,hd);const [pa]=pRange(hp,a-1);const st=pStats(a,b),pv=pStats(pa,a);const be=breakEven();const isNow=Date.now()>=a&&Date.now()<b;
  const isNow0=Date.now()>=a&&Date.now()<b;const pl={day:'اليوم',week:'الأسبوع',month:'الشهر'}[hp],plv={day:isNow0?'أمس':'اليوم اللي قبله',week:'الأسبوع اللي قبله',month:'الشهر اللي قبله'}[hp];
  const need=be.cups*Math.max(1,Math.ceil(st.days||1));const pct=need?Math.min(100,st.cups/need*100):0;
  const by={};st.sl.forEach(s=>s.items.forEach(i=>{const o=by[i.n]=by[i.n]||{q:0,pr:0,rev:0};o.q+=i.q;o.pr+=(i.price-i.cost)*i.q;o.rev+=i.price*i.q}));const allP=Object.entries(by).sort((x,y)=>y[1].pr-x[1].pr);const top=Object.entries(by).sort((x,y)=>y[1].rev-x[1].rev).slice(0,5);const hrs=Array(24).fill(0);st.sl.forEach(x=>hrs[new Date(x.t).getHours()]+=x.total);const hmn=hrs.findIndex(v=>v>0),hmx=23-hrs.slice().reverse().findIndex(v=>v>0),hm=Math.max(1,...hrs);const pays={};st.sl.forEach(x=>pays[x.pay]=(pays[x.pay]||0)+x.total);
  let chart='';if(hp!=='day'){const ds=[];for(let t=a;t<b;t+=DAY)ds.push({t,r:salesSum(inRange(S.sales,t,t+DAY)).rev});const mx=Math.max(1,...ds.map(x=>x.r));chart=`<div class="chart" style="height:110px">${ds.map(x=>`<div title="${f2(x.r)}"><i style="height:${x.r/mx*100}%;${x.t>Date.now()?'opacity:.25':''}"></i><span>${hp==='week'?WD[new Date(x.t).getDay()].slice(0,3):new Date(x.t).getDate()}</span></div>`).join('')}</div>`}
  return `<div class="card"><div class="row" style="gap:6px">${[['day','يوم'],['week','أسبوع'],['month','شهر']].map(([k,l])=>`<button class="btn sm ${k===hp?'':'ghost'}" data-a="hp" data-id="${k}">${l}</button>`).join('')}<span class="sp"></span><input type="date" id="hdate" value="${dk(hd)}" max="${dk(Date.now())}" style="width:auto;padding:5px 8px"></div>
   <div class="row" style="margin-top:10px;justify-content:center;gap:10px"><button class="btn ghost sm" data-a="hnav" data-id="-1">→ السابق</button><b style="font-size:16px;min-width:150px;text-align:center">${pLabel(hp,a,b)}</b><button class="btn ghost sm" data-a="hnav" data-id="1" ${b>Date.now()?'disabled style="opacity:.3"':''}>التالي ←</button></div>
   ${isNow?'':`<div style="text-align:center;margin-top:6px"><button class="btn sec sm" data-a="hnow">${{day:'رجوع لليوم',week:'رجوع للأسبوع الحالي',month:'رجوع للشهر الحالي'}[hp]}</button></div>`}</div>
  <div class="card"><div class="row"><h3 style="margin:0">💰 الدخل والمصروفات</h3><span class="sp"></span><button class="btn ghost sm" data-a="imp">📥 ملف الكاشير</button></div>
   <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px;margin-top:8px"><div class="kpi" style="padding:12px"><div class="l">الدخل</div><div class="v" style="font-size:24px">${C(Math.round(st.rev*10)/10)}</div><div class="s">${pv.rev?dlt(st.rev,pv.rev)+' عن '+plv:'&nbsp;'}</div></div>
    <button class="kpi" data-a="dexp" style="padding:12px;text-align:start;cursor:pointer;font:inherit;color:inherit;border:2px dashed var(--line)"><div class="l">🧾 مصروفات يومية ＋</div><div class="v neg" style="font-size:24px">${C(outOf(a,b))}</div><div class="s">${outN(a,b)?outN(a,b)+' بند':'اضغط للإضافة'}</div></button>
    <button class="kpi" data-a="dpur" style="padding:12px;text-align:start;cursor:pointer;font:inherit;color:inherit"><div class="l">🛒 مشتريات مقاضي</div><div class="v" style="font-size:24px;color:var(--acc)">${C(purL(a,b).reduce((s,p)=>s+(+p.total||0),0))}</div><div class="s">${purL(a,b).length?purL(a,b).length+' شراء':'من الاحتياج'}</div></button></div>${(()=>{const r=Math.round(st.rev*10)/10,o=outOf(a,b),nt=r-o;return `<div class="row" style="margin-top:8px;padding:12px;border-radius:12px;background:var(--bg)"><b>بعد المصروفات اليومية</b><span class="sp"></span><span class="mut" dir="ltr" style="font-size:13px">${f2(r)} − ${f2(o)}</span><b class="${nt>=0?'pos':'neg'}" style="font-size:22px;margin-inline-start:8px">${C(nt)}</b></div>`})()}${payRow(a,b,st)}</div>
  <div class="card"><h3>🏆 الأكثر مبيعاً</h3>${top.length?`<table><tr><th>الصنف</th><th>العدد</th><th>المبيعات</th></tr>${top.slice(0,4).map(([n,o],k)=>`<tr><td>${['🥇','🥈','🥉','4.'][k]} ${esc(n)}</td><td>${f2(o.q)}</td><td>${C(o.rev)}</td></tr>`).join('')}</table>`:'<div class="empty">ما فيه مبيعات في هذي الفترة</div>'}${allOrders(a,b,st,by)}</div>
  ${dailyChart(hp,a,b)}`}
function ordCount(a,b,st){const im=(S.imports||[]).filter(x=>x.day>=a&&x.day<b);const ids=new Set(im.map(x=>x.id));if(im.some(x=>!(x.orders>0)))return 0;return im.reduce((s,x)=>s+(x.orders||0),0)+st.sl.filter(x=>!x.imp||!ids.has(x.imp)).length}
function payRow(a,b,st){const P={};(S.imports||[]).filter(x=>x.day>=a&&x.day<b).forEach(x=>Object.entries(x.pay||{}).forEach(([k,v])=>{const kk=k==='كاش'?'كاش':'شبكة';P[kk]=(P[kk]||0)+v}));
  st.sl.filter(x=>!x.imp).forEach(x=>{const kk=/كاش|نقد/.test(x.pay||'')?'كاش':'شبكة';P[kk]=(P[kk]||0)+x.total});const t=(P['كاش']||0)+(P['شبكة']||0);if(!t)return'';
  const c=P['كاش']||0,n=P['شبكة']||0,pc=Math.round(c/t*100);
  return `<div class="row" style="margin-top:12px;gap:8px"><div class="kpi" style="flex:1;padding:10px"><div class="l">💵 كاش</div><div class="v" style="font-size:18px">${C(c)}</div><div class="s">${pc}%</div></div><div class="kpi" style="flex:1;padding:10px"><div class="l">💳 شبكة</div><div class="v" style="font-size:18px">${C(n)}</div><div class="s">${100-pc}%</div></div></div>
   <div style="display:flex;height:8px;border-radius:4px;overflow:hidden;margin-top:8px"><i style="width:${pc}%;background:var(--pri)"></i><i style="flex:1;background:var(--acc)"></i></div>`}
function allOrders(a,b,st,by){const E=Object.entries(by).sort((x,y)=>y[1].rev-x[1].rev);if(!E.length)return'';const oc=ordCount(a,b,st);const cups=E.reduce((s,[,o])=>s+o.q,0);
  return `<details style="margin-top:12px;background:var(--bg);border-radius:10px;padding:10px 12px"><summary style="cursor:pointer;font-weight:800">📋 كل الطلبات: ${oc?f2(oc)+' طلب · ':''}${f2(cups)} كوب · ${E.length} صنف</summary>
   <table style="margin-top:8px"><tr><th>الصنف</th><th>العدد</th><th>المبيعات</th></tr>${E.map(([n,o])=>`<tr><td>${esc(n)}</td><td>${f2(o.q)}</td><td>${C(o.rev)}</td></tr>`).join('')}</table></details>`}
const recL=(a,b)=>{const o=[];const end=Math.min(b,sod(Date.now())+DAY);(S.recur||[]).forEach(r=>{for(let d=Math.max(sod(a),sod(r.from));d<end;d+=DAY){if(r.to&&d>=r.to)break;if(d<a)continue;o.push({id:r.id,t:d+1,n:r.name+' 🔁',v:+r.amount||0,k:'r'})}});return o};
const outL=(a,b)=>[...recL(a,b),...inRange(S.expenses||[],a,b).map(e=>({id:e.id,t:e.t,n:e.cat,v:+e.amount||0,k:'e'}))].sort((x,y)=>y.t-x.t);
const purL=(a,b)=>{const ex=(S.expenses||[]).filter(e=>e.stocked);return inRange(S.purchases,a,b).filter(p=>!p.fromExp&&!ex.some(e=>e.t===p.t&&+e.amount===+p.total)).sort((x,y)=>y.t-x.t)};
A.dpur=()=>{const [a,b]=pRange(hp,hd);const L=purL(a,b);openM(`<h3>🛒 مشتريات مقاضي</h3><p class="mut">${pLabel(hp,a,b)} · المجموع <b>${C(L.reduce((s,p)=>s+(+p.total||0),0))}</b></p>
  ${L.length?`<table>${L.map(p=>{const i=ING(p.ing);const pk=i&&inPack(i);return `<tr><td>${esc(i?i.name:'—')}<div class="mut">${dk(p.t).slice(5)}${p.staff?' · '+esc(p.staff):''}</div></td><td>${pk?f2(r2(p.q/i.packSize))+' '+esc(i.pack||'كرتون'):f2(p.q)+' '+esc(i&&i.unit==='كجم'?'كيلو':(i?i.unit:''))}</td><td>${C(+p.total||0)}</td><td><button class="btn ghost sm" data-a="editpur" data-id="${p.id}">✏️</button></td></tr>`}).join('')}</table>`:'<div class="empty">ما فيه مشتريات. سجّلها من زر «اشتريت» في الاحتياج أو المخزون.</div>'}
  <div class="row" style="margin-top:12px"><button class="btn sec" data-a="gotoneeds">🛒 الاحتياج</button><span class="sp"></span><button class="btn ghost" data-a="close">إغلاق</button></div>`)};
A.gotoneeds=()=>{closeM();go('needs')};
const outOf=(a,b)=>outL(a,b).reduce((s,x)=>s+x.v,0),outN=(a,b)=>outL(a,b).length;
A.dexp=()=>{const [a,b]=pRange(hp,hd);const L=outL(a,b);const day=dk(hp==='day'?hd:Date.now());
  openM(`<h3>🧾 مصروفات يومية</h3><p class="mut">${pLabel(hp,a,b)} · المجموع <b>${C(L.reduce((s,x)=>s+x.v,0))}</b></p>
   <div class="card" style="margin:0 0 12px;background:var(--bg)"><label>وش اشتريت / وش صرفت؟</label><input id="dx_n" list="dx_l" placeholder="مثلاً: ثلج، غاز، كاسات…" autocomplete="off"><datalist id="dx_l">${[...new Set([...S.ings.map(i=>i.name),...(S.expenses||[]).map(e=>e.cat)])].map(n=>`<option value="${esc(n)}">`).join('')}</datalist>
   <label>السعر</label><input id="dx_v" type="number" inputmode="decimal" placeholder="0">
   <label>اليوم</label><input id="dx_d" type="date" value="${day}" max="${dk(Date.now())}">
   ${ISSTAFF?'':`<label style="display:flex;gap:8px;align-items:center;margin-top:10px"><input type="checkbox" id="dx_r" style="width:auto"> 🔁 يتكرر كل يوم (مثل مصروف العمال)</label>`}
   <button class="btn full" style="margin-top:10px" data-a="savedexp">＋ إضافة</button></div>
   ${(S.recur||[]).filter(r=>!r.to||r.to>Date.now()).length?`<div class="mut" style="margin:4px 0 8px">🔁 يتكرر كل يوم: ${(S.recur||[]).filter(r=>!r.to||r.to>Date.now()).map(r=>`<b>${esc(r.name)} ${f2(r.amount)}</b>${ISSTAFF?'':` <button class="btn ghost sm" style="padding:1px 7px" data-a="stoprecur" data-id="${r.id}">إيقاف</button>`}`).join(' · ')}</div>`:''}
   ${L.length?`<table>${L.map(x=>`<tr><td>${esc(x.n)}<div class="mut">${dk(x.t).slice(5)}${x.k==='p'?' · شراء':''}</div></td><td>${C(x.v)}</td><td>${x.k==='e'&&!ISSTAFF?`${(S.expenses||[]).find(e=>e.id===x.id&&e.stocked)?'<span class="tag t-ok">✓ بالمخزون</span> ':''}${!(S.expenses||[]).find(e=>e.id===x.id&&e.stocked)?`<button class="btn sec sm" data-a="e2p" data-id="${x.id}">📦 للمخزون</button> `:''}<button class="btn ghost sm" data-a="deldexp" data-id="${x.id}">✕</button>`:''}</td></tr>`).join('')}</table>`:'<div class="empty">ما فيه مصروفات مسجلة</div>'}
   <div class="row" style="margin-top:12px"><span class="sp"></span><button class="btn ghost" data-a="close">إغلاق</button></div>`);setTimeout(()=>{const e=$('#dx_n');if(e)e.focus()},50)};
A.savedexp=()=>{const n=val('dx_n'),v=num('dx_v');if(!n||!(v>0))return toast('اكتب الاسم والسعر');const d=val('dx_d')||dk(Date.now());
  const rc=$('#dx_r');if(rc&&rc.checked){S.recur=S.recur||[];S.recur.push({id:uid(),name:n,amount:v,from:new Date(d+'T00:00').getTime(),to:0});save('✓ انضاف كمصروف يومي');render();A.dexp();return}const t=d===dk(Date.now())?Date.now():new Date(d+'T12:00').getTime();
  S.expenses=S.expenses||[];const ne={id:uid(),t,cat:n,amount:v,note:'',daily:true,staff:window.CLOUD?CLOUD.userName:''};S.expenses.push(ne);save('✓ انضاف');render();const mi=!ISSTAFF&&ingByName(n);if(mi){A.qbuy(mi.id,{price:v,t,expId:ne.id})}else A.dexp()};
const ingByName=n=>{const k=mnorm(n||'');return S.ings.find(i=>mnorm(i.name)===k)};
const ingGuess=n=>{const k=mnorm(n||'');let best=null,bs=0;S.ings.forEach(i=>{const q=mnorm(i.name);let sc=0;if(q===k)sc=100;else if(k.includes(q)||q.includes(k))sc=50+Math.min(q.length,k.length);else{const GW=['مجمد','مجمده','ثلاجه','فريش','طازج','الري','كرتون','كيس','حبه','لب','عصير'];const w=k.split(' ').filter(x=>x.length>2&&!GW.includes(x));const hit=w.filter(x=>q.includes(x)).length;if(hit)sc=10*hit+q.length/10;else if(lev(k,q)<=2)sc=20}if(sc>bs){bs=sc;best=i}});return best};
A.e2p=id=>{const e=(S.expenses||[]).find(x=>x.id===id);if(!e)return;const ex=ingByName(e.cat);if(ex)return A.qbuy(ex.id,{price:e.amount,t:e.t,expId:e.id});const g=ingGuess(e.cat);
  openM(`<h3>📦 ${esc(e.cat)} → المخزون</h3><label>هذي أي مادة في المخزون؟</label><select id="e2_i"><option value="new">➕ مادة جديدة باسم «${esc(e.cat)}»</option>${ICATS.map(c=>{const L=S.ings.filter(i=>(i.cat||'أخرى')===c);return L.length?`<optgroup label="${esc(c)}">${L.map(i=>`<option value="${i.id}" ${g&&g.id===i.id?'selected':''}>${esc(i.name)}</option>`).join('')}</optgroup>`:''}).join('')}</select>
   <div id="e2_cw" style="${g?'display:none':''}"><label>النوع</label><select id="e2_c">${ICATS.map(c=>`<option ${c==='أخرى'?'selected':''}>${esc(c)}</option>`).join('')}</select></div>
   <div class="row" style="margin-top:16px"><span class="sp"></span><button class="btn ghost" data-a="close">إلغاء</button><button class="btn" data-a="e2pgo" data-id="${e.id}">التالي ←</button></div>`);
  $('#e2_i').onchange=ev=>{$('#e2_cw').style.display=ev.target.value==='new'?'':'none'}};
A.e2pgo=id=>{const e=(S.expenses||[]).find(x=>x.id===id);if(!e)return;let v=val('e2_i');if(v==='new'){const i={id:uid(),name:e.cat,unit:'كجم',stock:0,min:0,cost:0,cat:val('e2_c')||'أخرى',trk:true};S.ings.push(i);v=i.id}A.qbuy(v,{price:e.amount,t:e.t,expId:e.id})};
A.stoprecur=id=>ask('إيقاف هذا المصروف اليومي من بكرة؟ (الأيام اللي فاتت تبقى محسوبة)',()=>{const r=(S.recur||[]).find(x=>x.id===id);if(r)r.to=sod(Date.now())+DAY;save('✓ توقف');render()});
A.deldexp=id=>{S.expenses=(S.expenses||[]).filter(x=>x.id!==id);save('انحذف');render();A.dexp()};
function homeNotes(){const N=advise().filter(n=>n.lv==='b').slice(0,3);return N.length?`<div class="card">${N.map(n=>`<div class="alert a-b" style="margin:4px 0">🔴 ${n.t}</div>`).join('')}</div>`:''}
function dailyChart(kind,a,b){let s0,s1;if(kind==='day'){s1=a+DAY;s0=s1-14*DAY}else{s0=a;s1=b}const ds=[];for(let t=s0;t<s1;t+=DAY){const r=salesSum(inRange(S.sales,t,t+DAY)).rev;ds.push({t,r})}
  const mx=Math.max(1,...ds.map(x=>x.r));const n=ds.length;
  return `<div class="card"><h3>📊 المبيعات اليومية <span class="mut" style="font-size:13px">${kind==='day'?'آخر 14 يوم':''}</span></h3><div class="chart" style="height:170px;gap:${n>20?2:4}px">${ds.map(x=>`<div title="${dk(x.t)}: ${f2(x.r)}" data-a="hday" data-id="${x.t}" style="cursor:pointer"><span style="font-size:${n>20?8:10}px;writing-mode:${n>20?'vertical-rl':'horizontal-tb'}">${x.r?Math.round(x.r):''}</span><i style="height:${x.r/mx*100}%;${x.t>Date.now()?'opacity:.25':''}${kind==='day'&&x.t===a?';background:var(--acc)':''}"></i><span>${new Date(x.t).getDate()}</span></div>`).join('')}</div></div>`}
