let PIMP=null;
A.buymenu=()=>A.buy();A._oldbuymenu=()=>openM(`<h3>🧾 سجّل شراء</h3><div class="grid" style="grid-template-columns:1fr 1fr"><button class="pbtn" style="padding:18px 8px" data-a="buy"><div style="font-size:28px">✍️</div><b>أسجّل بنفسي</b><span>مادة وحدة</span></button><button class="pbtn" style="padding:18px 8px" data-a="pimp"><div style="font-size:28px">📥</div><b>مشتريات الموظفين</b><span>ملف من جدول Google</span></button></div><div class="row" style="margin-top:12px"><span class="sp"></span><button class="btn ghost" data-a="close">إغلاق</button></div>`);
A.pimp=()=>{openM(`<h3>📥 مشتريات الموظفين</h3><p class="mut">من جدول Google افتح ورقة «المشتريات» ← ملف ← تنزيل ← CSV أو Excel، وبعدها اختر الملف هنا. المشتريات اللي سحبتها قبل ما تتكرر.</p><input type="file" id="pimpf" accept=".csv,.xlsx,.xls,.txt"><div id="pimpb" style="margin-top:12px"></div><div class="row" style="margin-top:12px"><span class="sp"></span><button class="btn ghost" data-a="close">إغلاق</button></div>`);
  $('#pimpf').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;$('#pimpb').innerHTML='<div class="empty">جاري القراءة…</div>';
   try{await loadXLSX();const buf=await f.arrayBuffer();let wb;if(/\.(csv|txt)$/i.test(f.name)){let txt;try{txt=new TextDecoder('utf-8',{fatal:true}).decode(buf)}catch(_){txt=new TextDecoder('windows-1256').decode(buf)}wb=XLSX.read(txt.replace(/^﻿/,''),{type:'string',raw:true})}else wb=XLSX.read(buf,{type:'array',cellDates:true});
    const ws=wb.Sheets[wb.SheetNames.find(n=>n==='المشتريات')||wb.SheetNames[0]];const rows=XLSX.utils.sheet_to_json(ws,{header:1,raw:true,defval:''});const h=(rows[0]||[]).map(x=>String(x).trim());const ix=k=>h.indexOf(k);
    if(ix('المادة')<0||ix('الكمية')<0)throw 0;const done=new Set(S.pimpIds||[]);let skipped=0,noLine=0;const out=[];
    rows.slice(1).forEach(r=>{const id=String(r[ix('المعرف')]||'');if(id&&done.has(id)){skipped++;return}const mat=String(r[ix('المادة')]||'').trim(),q=toNum(r[ix('الكمية')]);if(!mat||q<=0){noLine++;return}
      const dv=r[ix('التاريخ')];const t=dv instanceof Date?dv.getTime():(Date.parse(String(dv).trim().replace(' ','T'))||toDate(dv,Date.now()));
      const k=norm(mat);const i=S.ings.find(x=>norm(x.name)===k)||S.ings.find(x=>norm(x.name).includes(k)||k.includes(norm(x.name)));
      out.push({id,t,mat,q,unit:String(r[ix('الوحدة')]||'').trim(),amt:toNum(r[ix('المبلغ')]),sup:String(r[ix('المورد')]||'').trim(),staff:String(r[ix('الموظف')]||'').trim(),img:String(r[ix('صورة')]||'').trim(),i})});
    PIMP=out;
    $('#pimpb').innerHTML=out.length?`<div class="tip">${out.length} سطر جديد${skipped?` · ${skipped} انسحبت قبل`:''}${noLine?` · ${noLine} فاتورة بدون تفاصيل`:''}</div><table>${out.map(x=>`<tr><td>${esc(x.mat)}${x.i?'':' <span class="tag t-w">جديد</span>'}<div class="mut">${esc(x.staff)} · ${dk(x.t).slice(5)}</div></td><td>${f2(x.q)} ${esc(x.unit)}</td><td>${x.amt?f2(x.amt):'—'}</td></tr>`).join('')}</table><p class="mut">المواد «الجديدة» بتنضاف للمخزون في قسم «أخرى»، وتقدر تعدلها بعدين.</p><button class="btn full" data-a="pimpgo">✓ سحب ${out.length} سطر</button>`:`<div class="alert a-ok">✅ ما فيه مشتريات جديدة${skipped?` (${skipped} سطر انسحب قبل)`:''}</div>`}
   catch(err){$('#pimpb').innerHTML='<div class="alert a-b">الملف مو من جدول المشتريات، أو فيه مشكلة. تأكد إنك نزّلت ورقة «المشتريات».</div>'}})};
A.pimpgo=()=>{if(!PIMP)return;S.pimpIds=S.pimpIds||[];let tot=0;PIMP.forEach(x=>{let i=x.i;if(!i){i={id:uid(),name:x.mat,unit:x.unit||'حبة',cost:0,stock:0,min:0,pack:'',packSize:0,yield:0,cat:'أخرى'};S.ings.push(i)}
    let q=x.q;if(x.unit&&i.packSize&&x.unit!==i.unit&&(x.unit===i.pack||/كرتون|كيس|جالون|باكيت|علبة|سطل/.test(x.unit)))q=x.q*i.packSize;
    const total=x.amt>0?x.amt:q*i.cost;const old=Math.max(0,i.stock);if(total>0)i.cost=r2((old*i.cost+total)/(old+q))||i.cost;i.stock=r2(i.stock+q);i.stockAt=Date.now();
    S.purchases.push({id:uid(),t:x.t,ing:i.id,q,total,sup:x.sup,staff:x.staff,img:x.img});S.extraList=(S.extraList||[]).filter(e=>e.i!==i.id);if(x.id)S.pimpIds.push(x.id);tot+=total});
  if(S.pimpIds.length>5000)S.pimpIds=S.pimpIds.slice(-5000);const n=PIMP.length;PIMP=null;closeM();save('✓ انسحب '+n+' سطر بقيمة '+f2(tot));render()};
A.matsCopy=()=>copy(S.ings.map(i=>[i.name,i.unit,i.pack||'',i.cat||'أخرى'].join('\t')).join('\n'));

