window.APP={getS:()=>S,render:()=>render(),toast:m=>toast(m),
  mergeInbox(rows){let n=0,tot=0;rows.forEach(x=>{const mat=String(x.mat||'').trim(),qq=+x.qty||0;if(!mat||qq<=0)return;const k=norm(mat);
    let i=S.ings.find(y=>norm(y.name)===k)||S.ings.find(y=>norm(y.name).includes(k)||k.includes(norm(y.name)));if(!i){i={id:uid(),name:mat,unit:x.unit||'حبة',cost:0,stock:0,min:0,pack:'',packSize:0,yield:0,cat:'أخرى'};S.ings.push(i)}
    let q=qq;const un=String(x.unit||'');if(un&&i.packSize&&un!==i.unit&&(un===i.pack||/كرتون|كيس|جالون|باكيت|علبة|سطل/.test(un)))q=qq*i.packSize;
    const total=+x.amount>0?+x.amount:q*i.cost;const old=Math.max(0,i.stock);if(total>0)i.cost=r2((old*i.cost+total)/(old+q))||i.cost;i.stock=r2(i.stock+q);i.stockAt=Date.now();
    const t=x.purchase_date?new Date(x.purchase_date+'T12:00').getTime():Date.parse(x.created_at)||Date.now();
    S.purchases.push({id:uid(),t,ing:i.id,q,total,sup:x.supplier||'',staff:x.staff||'',imgPath:x.img_path||''});S.extraList=(S.extraList||[]).filter(e=>e.i!==i.id);n++;tot+=total});
    if(n){save();render()}return{n,tot}}};

