const UIK='juice_ui_v1';let restoreY=null;
function saveUI(){try{localStorage.setItem(UIK,JSON.stringify({showAll,yx,ymode,hp,tab,scat,icat,stcat,tvc,tvp,ysz,yf,yp,yc,yn,pay,cart,y:window.scrollY||0,t:Date.now()}));sessionStorage.setItem(UIK,'1')}catch(e){}}
(function(){try{const u=JSON.parse(localStorage.getItem(UIK)||'null');if(!u||Date.now()-u.t>6*36e5)return;const h=(location.hash||'').slice(1);
  if(!TABS.find(t=>t[0]===h)&&TABS.find(t=>t[0]===u.tab))tab=u.tab;if(!h||h===u.tab)restoreY=u.y;
  scat=u.scat||scat;icat=u.icat||icat;stcat=u.stcat||stcat;tvc=u.tvc||tvc;tvp=u.tvp||tvp;ysz=u.ysz||ysz;yf=u.yf||yf;yp=u.yp||yp;yc=u.yc||yc;yn=u.yn||yn;pay=u.pay||pay;hp=u.hp||hp;showAll=!!u.showAll;ymode=u.ymode||ymode;if(Array.isArray(u.yx))yx=u.yx;if(u.cart&&typeof u.cart==='object')cart=u.cart}catch(e){}})();
let sT;window.addEventListener('scroll',()=>{clearTimeout(sT);sT=setTimeout(saveUI,300)},{passive:true});
const _render=render;render=function(){_render();saveUI();lockUI()};
render();if(restoreY)setTimeout(()=>scrollTo(0,restoreY),60);
